import SwiftUI

enum AgentforceStudyBank {
    static let sections: [StudySection] = [
        // Section 1: Prompt Engineering (43 topics)
        StudySection(
            id: "prompt-engineering",
            title: "Prompt Engineering",
            color: Color(red: 0.31, green: 0.27, blue: 0.90),
            lightColor: Color(red: 0.93, green: 0.95, blue: 1.0),
            icon: "pencil.and.outline",
            objectives: [
                StudyObjective(
                    id: "pe-access-controls",
                    title: "Identify access controls governing prompt templates",
                    topics: [
                        StudyTopic(id: "pe-access-controls-1", number: 1, question: "Which permission set or license is required to create and manage prompt templates in Prompt Builder?", answer: "The 'Einstein Generative AI' permission set license (PSL) is required at the org level. Individually, users need either the 'Prompt Template Manager' permission set (to create, edit, activate) or 'Prompt Template User' (runtime invocation only). Admins assign these via Setup > Permission Sets."),
                        StudyTopic(id: "pe-access-controls-2", number: 2, question: "The distinction between users who can view vs. edit/activate prompt templates, and what controls that separation.", answer: "'Prompt Template User' grants runtime invocation only — the user can trigger a template but cannot open, edit, or activate it. 'Prompt Template Manager' grants full lifecycle access: create, edit, activate, and deactivate. The separation is enforced by the specific system permissions bundled in each permission set."),
                        StudyTopic(id: "pe-access-controls-3", number: 3, question: "How do prompt template sharing rules and workspace visibility differ from standard record sharing?", answer: "Prompt templates are metadata-level artifacts, not records, so standard OWD/sharing rules do NOT apply. Access is governed entirely by permission sets (Manager vs. User). Workspace visibility in Prompt Builder is also permission-driven — only users with Manager permissions see the full authoring workspace."),
                        StudyTopic(id: "pe-access-controls-4", number: 4, question: "Distinction between 'Prompt Template User' and 'Prompt Template Manager' permissions.", answer: "'Prompt Template User': runtime invocation only — can call an active template from a Flow, Apex, or agent action but cannot edit or activate. 'Prompt Template Manager': full authoring rights — create, edit, test, activate, and deactivate templates. Both require the underlying Einstein Generative AI PSL."),
                        StudyTopic(id: "pe-access-controls-5", number: 5, question: "Which Salesforce Setup location is used to assign Prompt Builder access to users?", answer: "Setup > Permission Sets > [Select the PSL or permission set] > Manage Assignments. You can also assign via Setup > Users > [specific user] > Permission Set Assignments. The org must also have Einstein Generative AI enabled under Setup > Einstein > Einstein Settings."),
                        StudyTopic(id: "pe-access-controls-6", number: 6, question: "How do object-level and field-level security (FLS) interact with prompt template execution?", answer: "Prompt templates merge data in the context of the running user. If the running user lacks FLS access to a field referenced in a merge field or grounding expression, that field returns blank/null — it does NOT throw an error. This means invisible data gaps can silently degrade response quality. Always ensure the agent/integration user has appropriate FLS for all referenced fields.")
                    ]
                ),
                StudyObjective(
                    id: "pe-trust-layer",
                    title: "Identify the security and privacy features of the Trust Layer",
                    topics: [
                        StudyTopic(id: "pe-trust-layer-1", number: 1, question: "The five core components of the Einstein Trust Layer.", answer: "1. Data Masking — PII/sensitive data is replaced with tokens before leaving Salesforce. 2. Toxicity Detection — screens prompts and responses for harmful content. 3. Zero Data Retention — LLM providers contractually cannot store Salesforce data. 4. Audit Trail — all LLM interactions logged in the Einstein AI Audit Trail. 5. Grounding — anchors LLM output to real CRM data to reduce hallucinations."),
                        StudyTopic(id: "pe-trust-layer-2", number: 2, question: "How does the Trust Layer's data masking feature protect PII?", answer: "Before the prompt is sent to the external LLM, Salesforce identifies PII tokens (names, emails, phone numbers, IDs) and replaces them with placeholder tokens (e.g., [PERSON_1]). The LLM never sees the raw PII. After the LLM returns its response, Salesforce re-substitutes the real values back into the output before delivering it to the end user."),
                        StudyTopic(id: "pe-trust-layer-3", number: 3, question: "How does grounding within the Trust Layer help prevent hallucinations?", answer: "Grounding injects verified Salesforce CRM data (records, fields, related data) directly into the prompt so the LLM reasons from factual context rather than general training knowledge. This anchors responses to actual business data — e.g., injecting the real opportunity amount and stage rather than letting the model guess — significantly reducing hallucination risk."),
                        StudyTopic(id: "pe-trust-layer-4", number: 4, question: "Given a compliance requirement that no customer data leaves Salesforce infrastructure, which Trust Layer feature satisfies it?", answer: "Zero Data Retention (ZDR). Salesforce has contractual agreements with supported LLM providers (e.g., OpenAI, Azure OpenAI) prohibiting them from storing, training on, or logging prompt/response data. To verify: Setup > Einstein > Einstein Trust Layer > confirm ZDR is active for your configured model. Only models with ZDR agreements appear in the approved model list."),
                        StudyTopic(id: "pe-trust-layer-5", number: 5, question: "PII re-identification (unmasking): how does the Trust Layer re-substitute masked tokens back into the response?", answer: "Salesforce maintains a session-scoped token map of [PLACEHOLDER] → real value. After the LLM returns its response with placeholder tokens, the Einstein Trust Layer replaces each token with the corresponding real value before the response is surfaced to the Salesforce UI or API caller. This happens server-side within Salesforce infrastructure, maintaining data integrity without exposing PII to the LLM."),
                        StudyTopic(id: "pe-trust-layer-6", number: 6, question: "What does 'zero data retention' mean in the context of the Einstein Trust Layer?", answer: "ZDR means the LLM provider is contractually bound to NOT store, log, use for training, or retain any prompt or response data after processing. The data flows in, is used for one inference call, and is immediately discarded by the provider. Salesforce enforces this through DPA agreements with approved providers. Only ZDR-compliant providers are listed in Einstein AI Setup."),
                        StudyTopic(id: "pe-trust-layer-7", number: 7, question: "What does toxicity detection in the Trust Layer screen for, and at which point in the lifecycle does it run?", answer: "Toxicity detection screens for harmful, abusive, hate speech, or otherwise unsafe content. It runs at TWO points: (1) on the outbound prompt before sending to the LLM, and (2) on the inbound LLM response before delivering to the user. The screening uses a separate safety classifier model."),
                        StudyTopic(id: "pe-trust-layer-8", number: 8, question: "What happens when toxicity detection flags content in a prompt or LLM response?", answer: "If the outbound prompt is flagged: the request is blocked and the LLM is never called — the user receives a safe error message. If the LLM's response is flagged: the response is suppressed and replaced with a safe fallback message. In both cases, the event is logged in the Einstein AI Audit Trail for administrator review."),
                        StudyTopic(id: "pe-trust-layer-9", number: 9, question: "Where are Einstein Trust Layer audit logs stored and how do you access them?", answer: "Audit logs are stored as Einstein Prompt Template Audit records, accessible via: Setup > Einstein > Einstein Trust Layer > Audit Trail. You can also query the EinsteinLLMInteraction__c object (or equivalent API object) via SOQL, or use the Data Export service. Logs capture prompt content, response, model used, user, timestamp, and masking/toxicity events."),
                        StudyTopic(id: "pe-trust-layer-10", number: 10, question: "Which events does the Einstein Trust Layer audit trail log?", answer: "Logged events include: prompt template invocation (user, timestamp, template name), the resolved prompt text, the LLM response, model used, any masking replacements applied, toxicity screening results, and whether the response was blocked. This provides a full end-to-end record for compliance review."),
                        StudyTopic(id: "pe-trust-layer-11", number: 11, question: "Which third-party LLM providers honor the Einstein Trust Layer zero data retention policy?", answer: "As of 2025, approved ZDR-compliant providers include OpenAI (via Azure OpenAI Service), Anthropic (Claude models), Google (Vertex AI), and select others listed in Setup. Only providers who have signed Salesforce's DPA with ZDR terms appear as options. Third-party providers without ZDR agreements cannot be used with the Trust Layer.")
                    ]
                ),
                StudyObjective(
                    id: "pe-model-management",
                    title: "Explain how to manage and prevent specific models from being accessed",
                    topics: [
                        StudyTopic(id: "pe-model-management-1", number: 1, question: "Where in Salesforce Setup does an administrator configure which LLM models are available to the org?", answer: "Setup > Einstein > AI Model Management (also called Einstein AI Settings in some orgs). Here admins see the list of available models, can set an org-wide default model, block specific models, and configure model-specific settings. This is the single control plane for all generative AI model access."),
                        StudyTopic(id: "pe-model-management-2", number: 2, question: "How do you block or restrict access to a specific model (e.g., a third-party provider model)?", answer: "In Setup > Einstein > AI Model Management, locate the model and toggle its status to 'Blocked' or 'Disabled'. Once blocked, no prompt template in the org can invoke that model — attempts return an error. This is org-wide and cannot be overridden at the template level."),
                        StudyTopic(id: "pe-model-management-3", number: 3, question: "Given a requirement to ensure all AI generation uses only Salesforce-hosted models, what configuration steps must an admin take?", answer: "1. Go to Setup > Einstein > AI Model Management. 2. Block all non-Salesforce-hosted models (e.g., external OpenAI direct, third-party providers). 3. Set a Salesforce-native model (e.g., Einstein built-in) as the org default. 4. Verify no active prompt templates reference a blocked model. 5. Confirm via audit trail that subsequent invocations use only the approved model."),
                        StudyTopic(id: "pe-model-management-4", number: 4, question: "Runtime behavior when a prompt template references a model that has been subsequently blocked.", answer: "The invocation FAILS with an error — it does NOT silently fall back to the org default model. The template invocation returns an error to the calling Flow, Apex, or agent action, which must handle the error gracefully. Admins should update the template to reference an allowed model before re-activating."),
                        StudyTopic(id: "pe-model-management-5", number: 5, question: "The difference between setting a default model versus blocking a model.", answer: "Setting a default model: specifies which model is used when a template has no explicit model assignment ('Let Salesforce decide'). It does NOT prevent templates from specifying another model. Blocking a model: absolutely prevents any template from invoking that model, regardless of explicit assignment. Blocking overrides any template-level model selection.")
                    ]
                ),
                StudyObjective(
                    id: "pe-when-to-use",
                    title: "Given business requirements, identify when it's appropriate to use Prompt Builder",
                    topics: [
                        StudyTopic(id: "pe-when-to-use-1", number: 1, question: "In which situations is Prompt Builder the correct tool rather than an out-of-the-box Einstein AI feature?", answer: "Use Prompt Builder when: you need to generate customized content (emails, summaries, recommendations) using specific Salesforce record data with a tailored prompt; when no out-of-the-box Einstein feature covers the exact output format or business logic; when you need full control over the prompt structure, grounding source, and LLM model selection; or when the output needs to feed into a Flow, Apex process, or agent action."),
                        StudyTopic(id: "pe-when-to-use-2", number: 2, question: "When would Prompt Builder be unnecessary or redundant compared to a pre-built Einstein capability?", answer: "Prompt Builder is redundant when: Einstein for Sales already provides the needed email drafting (Einstein Sales Emails); Einstein Case Classification already handles case routing; Einstein Article Recommendations already surfaces knowledge for service agents; or Einstein Opportunity Scoring already provides the needed scoring. Use the out-of-the-box features first — reach for Prompt Builder only when standard features cannot meet the specific requirement."),
                        StudyTopic(id: "pe-when-to-use-3", number: 3, question: "A company wants to auto-generate a personalized email draft pre-populated with opportunity data when a sales rep clicks a button. Which tool should they use?", answer: "Prompt Builder with a Flex prompt template type (or Sales Email type if available). The admin creates a template that merges Opportunity fields (amount, stage, product, close date, contact name) into a custom prompt, then invokes it via a Flow triggered by the button click. The generated draft is surfaced to the rep for review before sending."),
                        StudyTopic(id: "pe-when-to-use-4", number: 4, question: "Key differences between a Prompt Template in Prompt Builder versus a custom Agentforce agent action to invoke AI logic.", answer: "Prompt Builder template: reusable, record-context-driven content generation invoked by users, Flows, or agents. Best for structured content output (emails, summaries). Agent action: an action the agent's reasoning engine selects dynamically based on user intent. Best for multi-step tasks, data retrieval, record updates, or external callouts. An agent action CAN invoke a Prompt Template — they are complementary, not mutually exclusive.")
                    ]
                ),
                StudyObjective(
                    id: "pe-grounding",
                    title: "Given a scenario, identify the appropriate grounding technique",
                    topics: [
                        StudyTopic(id: "pe-grounding-1", number: 1, question: "What distinguishes static grounding (merge fields) from dynamic grounding (Flow, Apex, Data Cloud) in prompt templates?", answer: "Static grounding (merge fields): pulls a fixed set of field values from the record in context at the time of invocation. Simple and fast — no additional logic. Dynamic grounding (Flow, Apex, Data Cloud): executes logic, queries, or external callouts to fetch computed or aggregated data before injecting it into the prompt. Needed when data requires transformation, multiple records, or real-time external sources."),
                        StudyTopic(id: "pe-grounding-2", number: 2, question: "How do merge fields provide grounding in a Prompt Builder template?", answer: "Merge fields are placeholders like {!$Record.Field__c} that Salesforce resolves at runtime by reading the field value from the record in context. They are inserted directly into the prompt body. When the template executes, each merge field is replaced with the actual field value before the prompt is sent to the LLM. They require no additional automation — just field-level access."),
                        StudyTopic(id: "pe-grounding-3", number: 3, question: "Which types of Salesforce data can merge fields inject into a Prompt Builder template?", answer: "Merge fields can inject: standard and custom fields from the primary record object, related record fields via relationship traversal (e.g., {!$Record.Account.Name}), User fields ({!$User.FirstName}), and Organization fields ({!$Organization.Name}). They cannot inject aggregated data, cross-object queries, or external data — those require Flow or Apex grounding."),
                        StudyTopic(id: "pe-grounding-4", number: 4, question: "When should a Flow be used as a grounding technique rather than a direct merge field?", answer: "Use a Flow when: data requires logic or transformation (e.g., calculate days since last contact); you need data from multiple related records; you need to aggregate child records (e.g., all open cases for an account); the data requires conditional logic before injection; or you need to call an external system. Flows return a text string that is injected into the prompt as a grounding block."),
                        StudyTopic(id: "pe-grounding-5", number: 5, question: "How is an Apex method configured and used as a grounding source within a Prompt Builder template?", answer: "The Apex method must be annotated with @InvocableMethod and return a List<String> or a wrapper class result. In Prompt Builder, the admin selects 'Apex' as the grounding type and selects the invocable Apex class. The method receives the record ID as input, performs its logic (queries, callouts, computation), and returns the grounding text string that is injected into the prompt."),
                        StudyTopic(id: "pe-grounding-6", number: 6, question: "How can administrators use Data Cloud Data Model Objects (DMOs) as grounding sources in a Prompt Template?", answer: "In Prompt Builder, select 'Data Cloud' as the grounding source, then choose the relevant DMO (e.g., Unified Individual, Product, Segment). Salesforce runs a vector or SOQL-style query against the DMO to retrieve relevant context. This is used for unstructured content retrieval (semantic search) or structured unified profile data. Requires Data Cloud provisioning and CRM connector setup."),
                        StudyTopic(id: "pe-grounding-7", number: 7, question: "An administrator needs to include real-time inventory data from an external ERP system. Which grounding approach is most appropriate?", answer: "Apex grounding. A Flow could also work via an external service call, but Apex gives more control for complex callout logic, error handling, and data transformation. The Apex @InvocableMethod calls the ERP REST API using a Named Credential, parses the response, and returns a formatted string injected into the prompt. Named Credentials must be configured in Setup for the external endpoint."),
                        StudyTopic(id: "pe-grounding-8", number: 8, question: "A company wants to ground a prompt template with unstructured knowledge articles and product documentation stored in Data Cloud. Which grounding technique?", answer: "Data Cloud grounding with a Vector/Retriever configuration. The admin indexes knowledge articles and documents in Data Cloud (via Agentforce Data Library or Data Cloud ingestion), then configures the prompt template to use a Data Cloud retriever grounding source. At runtime, a semantic similarity search retrieves the most relevant chunks and injects them as context."),
                        StudyTopic(id: "pe-grounding-9", number: 9, question: "What strategies handle null or missing data from a grounding source without causing hallucinations?", answer: "1. Add explicit null checks in Flow/Apex before injecting data — return a 'No data available' string rather than null. 2. Include instructions in the prompt: 'If no data is provided for a field, state that the information is unavailable rather than guessing.' 3. Use conditional merge field syntax where available. 4. Test templates against records with incomplete data in Preview mode before activating.")
                    ]
                ),
                StudyObjective(
                    id: "pe-lifecycle",
                    title: "Explain the process for creating, activating, and executing prompt templates",
                    topics: [
                        StudyTopic(id: "pe-lifecycle-1", number: 1, question: "What are the steps to create and activate a prompt template in Prompt Builder?", answer: "1. Setup > Einstein > Prompt Builder > New. 2. Select template type (Field Generation, Flex, Sales Email, Record Summary). 3. Select the primary object (if applicable). 4. Build the prompt body using merge fields, grounding sources, and static text. 5. Select the LLM model. 6. Preview/test the template against a real record. 7. Click Activate to make it available for invocation. The template moves from Draft to Active state."),
                        StudyTopic(id: "pe-lifecycle-2", number: 2, question: "What lifecycle states can a prompt template exist in?", answer: "Draft: template is being built/edited — cannot be invoked. Active: template is live and can be invoked by users, Flows, Apex, or agent actions. Inactive/Deactivated: was previously active, now suspended — cannot be invoked. Only ONE version can be Active at a time per template. Draft versions can coexist with an Active version."),
                        StudyTopic(id: "pe-lifecycle-3", number: 3, question: "What does activating a prompt template enable?", answer: "Activation makes the template invocable at runtime. Active templates can be: triggered by a user via Einstein features (Field Generation inline button); called from a Flow via the 'Prompt Template' action; called from Apex via the ConnectApi.EinsteinLLM methods; or invoked by an Agentforce agent action. Only Active templates appear as selectable options in Flow/agent action builders."),
                        StudyTopic(id: "pe-lifecycle-4", number: 4, question: "What does each prompt template lifecycle state allow or restrict?", answer: "Draft: editable, testable via Preview, NOT invocable in production flows/agents. Active: NOT directly editable (must create a new Draft version to edit), fully invocable. Deactivated: NOT editable, NOT invocable — preserved as a historical record. To edit an Active template: create a new Draft version, edit it, then activate the new version (which deactivates the previous Active version)."),
                        StudyTopic(id: "pe-lifecycle-5", number: 5, question: "What prerequisites must be met before a prompt template can be activated?", answer: "1. Einstein Generative AI must be enabled in Setup. 2. The template must have a valid prompt body (no syntax errors). 3. All merge fields must reference valid fields on the selected object. 4. All grounding sources (Flows, Apex) must exist and be accessible. 5. A model must be assigned (or org default configured). 6. The activating user must have 'Prompt Template Manager' permission."),
                        StudyTopic(id: "pe-lifecycle-6", number: 6, question: "How is a prompt template previewed and tested within Prompt Builder before activation?", answer: "In Prompt Builder, use the Preview pane (right side of the authoring screen). Select a specific record from the org (by searching for a record ID/name), then click 'Generate'. The resolved prompt is shown (with merge fields filled in) alongside the LLM's actual response. This uses real org data and real LLM inference — Einstein credits are consumed during preview."),
                        StudyTopic(id: "pe-lifecycle-7", number: 7, question: "How can an administrator invoke an active Flex prompt template from within an Agentforce agent action?", answer: "Create a custom agent action of type 'Prompt Template' and select the active Flex template. Map the record ID (or other required inputs) to the template's input parameters. The agent's reasoning engine can then invoke this action when appropriate. Alternatively, wrap the template invocation in a Flow and expose that Flow as an agent action."),
                        StudyTopic(id: "pe-lifecycle-8", number: 8, question: "How does versioning work for Prompt Templates?", answer: "Saving a template in Draft state does NOT automatically create a new version — it overwrites the current draft. To create a new version, you must explicitly choose 'Save as New Version.' Versions are numbered sequentially. Only one version can be Active at a time. When you activate a new version, the previously Active version is automatically deactivated. Prior versions are retained as Inactive records for audit/rollback purposes. You can view version history in the template's detail page."),
                        StudyTopic(id: "pe-lifecycle-9", number: 9, question: "How can an administrator revert a Prompt Template to a previously active version?", answer: "Navigate to the template's version history, select the desired previous Inactive version, and Activate it. This deactivates the current Active version and promotes the selected version to Active. Note: you cannot directly edit a deactivated version — clone it as a new Draft if edits are needed before re-activation.")
                    ]
                ),
                StudyObjective(
                    id: "pe-template-types",
                    title: "Identify the considerations for using a prompt template type such as field generation and flex types",
                    topics: [
                        StudyTopic(id: "pe-template-types-1", number: 1, question: "What is the purpose of the Field Generation prompt template type?", answer: "Field Generation templates auto-populate a specific field on a Salesforce record using AI. They are bound to one specific object and one specific field. When triggered, the LLM generates text that is pre-filled into the field, allowing the user to review and save. Classic use case: auto-generate a Case Summary field, a product description, or a call notes field."),
                        StudyTopic(id: "pe-template-types-2", number: 2, question: "Where does the output of a Field Generation prompt template appear in the Salesforce UI?", answer: "The output appears as a suggested value in the specific field it is bound to, displayed inline on the record page with an 'Accept' / 'Edit' prompt. The user must explicitly accept the suggestion before it is saved to the record — it is NOT auto-saved. The Einstein icon next to the field triggers the generation."),
                        StudyTopic(id: "pe-template-types-3", number: 3, question: "How does the Flex prompt template type differ from Field Generation in terms of output target and invocation?", answer: "Field Generation: bound to a specific object field, triggered from the record UI, output pre-fills that field. Flex: NOT bound to any specific field or object — it is a general-purpose template invoked programmatically via Flow, Apex, or agent actions. Output is returned as a string to the calling process. The caller decides how to use/display the output."),
                        StudyTopic(id: "pe-template-types-4", number: 4, question: "What is the Sales Email prompt template type in Prompt Builder?", answer: "Sales Email is a specialized template type designed to generate outreach emails for sales use cases. It integrates with Einstein Sales Emails and can be triggered from Lead/Contact/Opportunity records. It uses merge fields from the record context (prospect name, company, opportunity details) and supports the email composer in Salesforce. It has a built-in email structure (subject, body)."),
                        StudyTopic(id: "pe-template-types-5", number: 5, question: "When is the Sales Email prompt template type the correct choice over a generic Flex template?", answer: "Use Sales Email when: the output needs to appear directly in the Salesforce email composer for a rep to review/send; you want integration with Einstein Sales Activity features; the use case is specifically sales outreach for Leads, Contacts, or Opportunities. Use Flex when: the email content is generated for programmatic use, the channel is not the native Salesforce email composer, or the use case is non-sales."),
                        StudyTopic(id: "pe-template-types-6", number: 6, question: "What is the purpose of the Record Summary prompt template type?", answer: "Record Summary generates a natural-language summary of a Salesforce record — bringing together multiple fields and related data into a coherent narrative. It appears as an 'Einstein Summary' panel on the record page. Best for Case summaries, Account briefs, Opportunity recaps. The output is display-only — it does not populate an editable field."),
                        StudyTopic(id: "pe-template-types-7", number: 7, question: "How does Record Summary behavior differ from Field Generation?", answer: "Record Summary: read-only display panel showing a generated summary — does NOT pre-fill an editable field, user cannot directly edit/save the AI output to a field. Field Generation: fills a specific editable field with AI-generated text that the user can accept or modify. Record Summary is for consumption/reading; Field Generation is for data entry assistance."),
                        StudyTopic(id: "pe-template-types-8", number: 8, question: "Key considerations when choosing between Field Generation and Flex for a business requirement.", answer: "Choose Field Generation when: the output must directly populate a specific record field, the trigger is user-initiated from the record page, and you want the native Einstein UI experience. Choose Flex when: the output is consumed by automation (Flow, Apex, agent), the output doesn't directly map to a single field, the invocation is programmatic/batch, or the use case is multi-step."),
                        StudyTopic(id: "pe-template-types-9", number: 9, question: "If multiple Field Generation prompt templates are active for the same field, how does Salesforce determine which one to execute?", answer: "Only ONE Field Generation template can be active per field per object. If you attempt to activate a second template for the same field, Salesforce will deactivate the existing one. This is enforced at the platform level — there is no priority or conflict resolution mechanism because the platform prevents the conflict from occurring."),
                        StudyTopic(id: "pe-template-types-10", number: 10, question: "What are the input character and token limits for Field Generation prompt templates?", answer: "The total prompt (template body + resolved merge fields + grounding content) must stay within the model's context window — typically 4,000–8,000 tokens for standard models, up to 128K for larger models. Individual text fields used as merge field inputs should be trimmed if they risk exceeding limits. The Field Generation template builder shows a token estimator to help manage this.")
                    ]
                ),
                StudyObjective(
                    id: "pe-best-practices",
                    title: "Explain how to implement best practices for writing effective prompts",
                    topics: [
                        StudyTopic(id: "pe-best-practices-1", number: 1, question: "What prompt-writing best practices reduce the likelihood of hallucinations or off-topic responses?", answer: "1. Be explicit and specific — tell the model exactly what to do and not do. 2. Provide grounded context — inject real record data rather than relying on the model's general knowledge. 3. Use output constraints — specify format, length, and what to include/exclude. 4. Add negative instructions — 'Do not fabricate information not present in the context.' 5. Use role assignment — 'You are a Salesforce customer service agent.' 6. Test with diverse records including edge cases."),
                        StudyTopic(id: "pe-best-practices-2", number: 2, question: "How should output instructions be structured to constrain the model's response to a desired format or length?", answer: "Place output instructions at the END of the prompt (they carry more weight there). Be explicit: 'Respond in exactly 3 bullet points, each under 20 words.' Use format examples: 'Format your response as: Subject: [one line]. Body: [3 paragraphs].' Specify what to omit: 'Do not include greetings or sign-offs.' Specify length: 'Limit your response to 150 words.'"),
                        StudyTopic(id: "pe-best-practices-3", number: 3, question: "What are common anti-patterns in prompt design that reduce reliability or quality?", answer: "Anti-patterns include: vague instructions ('summarize this' without specifying audience, length, or format); no negative constraints (model fills gaps with hallucinated content); over-reliance on the model's world knowledge without grounding; instructions that contradict each other; prompts that are too long (relevant instructions buried and diluted); missing error handling guidance for null/missing data."),
                        StudyTopic(id: "pe-best-practices-4", number: 4, question: "How can few-shot prompting techniques be implemented within a Prompt Builder template?", answer: "Include 2–3 input/output examples directly in the prompt body before the actual request. Format: 'Example 1: Input: [sample data]. Output: [desired response]. Example 2: ...' Then append: 'Now generate output for the following: {!$Record.FieldName}'. Few-shot examples calibrate the model on the exact tone, format, and depth expected without additional fine-tuning."),
                        StudyTopic(id: "pe-best-practices-5", number: 5, question: "How does the Einstein Trust Layer process prompt templates for toxicity, bias, and PII masking before sending to the LLM?", answer: "Processing order: 1. Prompt Builder resolves merge fields and grounding data into the final prompt string. 2. The Trust Layer scans the resolved prompt for PII tokens — replaces them with placeholders. 3. The toxicity/safety classifier screens the masked prompt. 4. If clean, the masked prompt is sent to the LLM. 5. LLM response returns — Trust Layer re-inserts real PII values. 6. Toxicity check on response. 7. Clean response delivered to user. All steps are logged.")
                    ]
                )
            ]
        ),
        // Section 2: Data 360 Fundamentals (17 topics)
        StudySection(
            id: "data-360",
            title: "Data 360 Fundamentals",
            color: Color(red: 0.06, green: 0.52, blue: 0.78),
            lightColor: Color(red: 0.88, green: 0.95, blue: 1.0),
            icon: "cylinder.split.1x2",
            objectives: [
                StudyObjective(
                    id: "d360-concepts",
                    title: "Explain foundational concepts of Data 360 such as chunking, indexing, and retrievers",
                    topics: [
                        StudyTopic(id: "d360-concepts-1", number: 1, question: "What is chunking: splitting large documents into smaller segments before indexing, and how chunk size affects retrieval quality.", answer: "Chunking is the process of dividing large documents (PDFs, articles, web pages) into smaller, manageable text segments before converting them to vector embeddings. Smaller chunks (e.g., 256 tokens) give more precise retrieval but may lose surrounding context. Larger chunks (e.g., 1024 tokens) retain more context but may dilute relevance signals. Optimal chunk size depends on the document type and query specificity."),
                        StudyTopic(id: "d360-concepts-2", number: 2, question: "Vector indexing in Data 360: converting text chunks into numerical embeddings for semantic similarity search.", answer: "Each text chunk is passed through an embedding model (e.g., text-embedding-ada-002) that converts it into a high-dimensional numerical vector. These vectors are stored in a vector database. At query time, the user's query is also converted to a vector, and cosine similarity (or similar metric) finds the stored chunks whose vectors are closest to the query vector — enabling semantic (meaning-based) search rather than keyword matching."),
                        StudyTopic(id: "d360-concepts-3", number: 3, question: "Keyword indexing in Data 360: term-frequency indexing for exact-match and BM25 search, and when it is preferred over vector search.", answer: "Keyword indexing (BM25/TF-IDF) indexes documents by the frequency and rarity of their terms. It excels at finding documents with exact keyword matches — particularly for product codes, error codes, proper nouns, or technical terms that embedding models may not represent well semantically. Prefer keyword search when queries use precise terminology unlikely to be paraphrased."),
                        StudyTopic(id: "d360-concepts-4", number: 4, question: "The difference between a keyword retriever and a vector retriever, including which query types each handles best.", answer: "Keyword retriever: finds exact or near-exact term matches. Best for: specific codes, names, acronyms, boolean queries. Weakness: misses synonyms and paraphrases. Vector retriever: finds semantically similar content even with different wording. Best for: natural language questions, conceptual queries, intent-based search. Weakness: can miss rare or specialized terms. Neither is universally superior — choose based on the expected query patterns."),
                        StudyTopic(id: "d360-concepts-5", number: 5, question: "Hybrid search in Data 360: combining vector and keyword retrievers using an ensemble approach.", answer: "Hybrid search runs both a vector retriever and a keyword retriever simultaneously, then merges their result sets using a ranking algorithm (e.g., Reciprocal Rank Fusion). This combines the semantic breadth of vector search with the precision of keyword search. It improves overall recall and precision — particularly useful when queries range from conversational ('How do I return a product?') to specific ('Error code 404-B troubleshooting')."),
                        StudyTopic(id: "d360-concepts-6", number: 6, question: "Individual retriever strategy versus ensemble retriever strategy: when to use each.", answer: "Individual (single) retriever: use when query types are uniform (all semantic OR all keyword). Simpler to configure and debug. Lower latency. Ensemble retriever: use when query types are mixed, when recall must be maximized, or when initial single-retriever results are insufficient. Tradeoff: slightly higher latency and complexity in result merging."),
                        StudyTopic(id: "d360-concepts-7", number: 7, question: "How chunk overlap is configured and why it reduces the chance of splitting a key sentence across chunk boundaries.", answer: "Chunk overlap defines a percentage of tokens repeated between consecutive chunks (e.g., 10–20% overlap). If a key sentence falls at the boundary of two chunks, overlap ensures it appears in full in at least one chunk. Without overlap, a critical sentence could be split mid-way, appearing incomplete in both chunks and potentially excluded from retrieval results."),
                        StudyTopic(id: "d360-concepts-8", number: 8, question: "Given an agent returning irrelevant answers about a technical manual, which Data 360 tuning lever is most likely to help?", answer: "Most likely fix: adjust chunk size (smaller chunks for more targeted retrieval) and/or switch from pure vector to hybrid retrieval. If the manual uses specialized technical terminology, a keyword retriever or hybrid approach will significantly improve precision. Also review top-K — if too many chunks are retrieved, irrelevant context may dilute the LLM's answer."),
                        StudyTopic(id: "d360-concepts-9", number: 9, question: "Top-K retriever configuration: how the number of chunks returned per query affects response quality.", answer: "Top-K defines how many chunks are retrieved and passed to the LLM as context. Low K (e.g., 3): focused context, lower token consumption, but may miss relevant information for broad queries. High K (e.g., 10+): more complete coverage but increases prompt token count, raises cost, and risks introducing irrelevant chunks that confuse the LLM. Tune K based on average query breadth and available context window size.")
                    ]
                ),
                StudyObjective(
                    id: "d360-adl",
                    title: "Explain the considerations of Agentforce Data Library and its concepts",
                    topics: [
                        StudyTopic(id: "d360-adl-1", number: 1, question: "What is the Agentforce Data Library?", answer: "The Agentforce Data Library (ADL) is Salesforce's managed repository for unstructured and semi-structured content used to ground Agentforce agents. It ingests documents (PDFs, Word files), web content, and Salesforce CMS articles, indexes them via vector/keyword embeddings backed by Data Cloud, and exposes them as knowledge sources agents can retrieve at runtime via the AnswerQuestionsWithKnowledge action."),
                        StudyTopic(id: "d360-adl-2", number: 2, question: "What types of data sources can the Agentforce Data Library ingest?", answer: "Three source categories: 1. File-based (SFDRIVE): PDFs, Word documents, PowerPoints, text files uploaded to Salesforce Files or external storage. 2. Web crawl: public-facing web pages crawled and indexed automatically. 3. Salesforce CMS / Knowledge: Salesforce Knowledge articles (published), CMS content. Each source type has different ingestion mechanics, refresh schedules, and size limits."),
                        StudyTopic(id: "d360-adl-3", number: 3, question: "What are the different Data Library source types available in Agentforce (file-based, web crawl, Salesforce CMS)?", answer: "SFDRIVE (file-based): manually uploaded files, supports PDFs/DOCX/TXT up to specified size limits. Web Crawl: configure a URL and crawl depth — Salesforce periodically re-crawls to keep content fresh. Knowledge/CMS: ingests published Salesforce Knowledge articles — automatically re-indexed when articles are published/updated. Each appears as a distinct 'source' in the ADL configuration."),
                        StudyTopic(id: "d360-adl-4", number: 4, question: "How do the different Data Library source types differ from each other?", answer: "SFDRIVE: manual upload, static until re-uploaded — good for product manuals, policy docs. Web Crawl: automated, periodic refresh — good for public-facing help centers or product sites. Knowledge: tightly integrated with Knowledge lifecycle (draft → review → published) — good for managed, versioned support content. The agent uses all configured sources as a unified retrieval pool."),
                        StudyTopic(id: "d360-adl-5", number: 5, question: "How are unstructured files such as PDFs and Word documents ingested into the Agentforce Data Library?", answer: "1. Admin navigates to Setup > Agentforce Data Library > New Source > File-Based. 2. Upload files or connect to a Salesforce Files library. 3. Salesforce extracts text content, chunks it, generates vector embeddings via the embedding model, and stores them in Data Cloud. 4. Indexing status can be monitored in ADL Setup (Pending > Indexing > Ready). 5. Once 'Ready', the source is available to agents using the knowledge action."),
                        StudyTopic(id: "d360-adl-6", number: 6, question: "When should an administrator use Agentforce Data Library versus structured Data Cloud data objects to ground an agent's responses?", answer: "Use ADL for unstructured or semi-structured content: PDFs, articles, knowledge bases, documentation — where retrieval requires semantic search. Use structured Data Cloud DMOs when: data is structured (records with defined fields), queries are data lookups (e.g., 'what is the customer's account balance'), and precision is needed. ADL is for 'find me relevant text'; Data Cloud DMOs are for 'give me this specific data point'."),
                        StudyTopic(id: "d360-adl-7", number: 7, question: "What data freshness and content refresh considerations apply to content in the Agentforce Data Library?", answer: "File-based (SFDRIVE): does NOT auto-refresh — admin must manually re-upload updated files and re-index. Web Crawl: refreshes on a configured schedule (daily/weekly) — set a crawl frequency appropriate to how often the site changes. Knowledge: auto-refreshes when articles are published or updated — no manual re-indexing needed. Always verify 'Last Indexed' timestamp in ADL Setup before major agent rollouts."),
                        StudyTopic(id: "d360-adl-8", number: 8, question: "What are the file size, file type, and volume limitations when ingesting unstructured documents into the Agentforce Data Library?", answer: "Supported file types: PDF, DOCX, TXT, HTML. File size limit per file: typically 5MB per file (check current Salesforce documentation for exact limits as they evolve). Total volume limits depend on org edition and Data Cloud storage. Very large files may fail indexing or produce poor chunks — split large documents into logical sections. Scanned PDFs (image-only) cannot be indexed — text must be extractable.")
                    ]
                )
            ]
        ),
        // Section 3: AI Agents (49 topics)
        StudySection(
            id: "ai-agents",
            title: "AI Agents",
            color: Color(red: 0.49, green: 0.27, blue: 0.90),
            lightColor: Color(red: 0.95, green: 0.93, blue: 1.0),
            icon: "cpu",
            objectives: [
                StudyObjective(
                    id: "agents-building-blocks",
                    title: "Explain how an agent works and its basic building blocks of agent script",
                    topics: [
                        StudyTopic(id: "agents-building-blocks-1", number: 1, question: "The role of the Agent System Prompt: how Salesforce constructs it at runtime from topics, instructions, and conversation history.", answer: "At each conversation turn, Salesforce dynamically constructs a system prompt by assembling: (1) global agent instructions, (2) the active topic's description and instructions, (3) available action descriptions, (4) conversation history (prior turns), and (5) any resolved variables. This assembled prompt is passed to the LLM, which uses it to decide whether to respond, call an action, or request more information from the user."),
                        StudyTopic(id: "agents-building-blocks-2", number: 2, question: "What is Agent Script within the context of an Agentforce agent and how does it shape behavior?", answer: "Agent Script is the pro-code authoring format for Agentforce agents — a YAML-based language that defines subagents, actions, variables, instructions, and deterministic control flow within an .agent file. It extends beyond pure declarative Agent Builder by enabling conditional branching, sequenced action execution, variable capture, and fine-grained routing logic that the GUI alone cannot express."),
                        StudyTopic(id: "agents-building-blocks-3", number: 3, question: "What is Agent Builder: the declarative interface in Salesforce for configuring topics, actions, and instructions.", answer: "Agent Builder is the point-and-click Setup interface for creating and managing Agentforce agents. Admins use it to: create topics (with descriptions and instructions), add/configure actions per topic, set topic filters, manage variables, preview conversations, and activate/deactivate agents. It is accessible via Setup > Agents > [Agent Name] > Open in Builder. It includes Canvas View (visual) and Script View (structured text)."),
                        StudyTopic(id: "agents-building-blocks-4", number: 4, question: "How does an Agentforce agent select and execute an action, then return a response?", answer: "1. User sends a message. 2. The reasoning engine (LLM) evaluates the message against all active topic descriptions. 3. It selects the best-matching topic. 4. Within that topic, it evaluates the message against action descriptions to pick the most appropriate action. 5. It invokes the action (Flow/Apex/prompt template). 6. The action returns output. 7. The LLM composes a natural-language response using the action output and topic instructions. 8. Response is delivered to the user."),
                        StudyTopic(id: "agents-building-blocks-5", number: 5, question: "How does an Agentforce agent evaluate user input against active topics during the reasoning loop?", answer: "The LLM uses embedding-based semantic matching and direct reasoning to compare the user's utterance against each topic's description and instructions. Topics with more precise, specific descriptions are preferred over vague ones. The LLM may also consider conversation history and active variable state. If no topic clearly matches, the agent falls back to the configured out-of-scope behavior."),
                        StudyTopic(id: "agents-building-blocks-6", number: 6, question: "How does the Agentforce LLM use topics, actions, and instructions to route a user request?", answer: "Topics act as routing buckets — the topic description is the matching signal. Instructions within the topic tell the LLM HOW to respond once in that topic. Actions are the tools the LLM can call — selected based on action description relevance to the specific user request. The LLM is given the combined topic+instructions+actions context and decides: which topic fits, which action to call (if any), and how to compose the final response."),
                        StudyTopic(id: "agents-building-blocks-7", number: 7, question: "The three foundational building blocks of an Agentforce agent: topics, actions, and instructions.", answer: "Topics: categorized domains of capability (e.g., 'Order Management', 'Technical Support') — each has a description the LLM uses for routing. Actions: specific tasks the agent can perform within a topic (Flows, Apex, prompt templates, external services) — each has a description the LLM uses to select the right tool. Instructions: natural-language directives within a topic or action that constrain LLM behavior, tone, and decision-making."),
                        StudyTopic(id: "agents-building-blocks-8", number: 8, question: "Out-of-scope handling: what the agent does when user input does not match any configured topic.", answer: "Default behavior: the agent returns a standard out-of-scope message (e.g., 'I'm sorry, I can't help with that. Is there something else I can assist you with?'). Custom configuration: admins can configure a custom out-of-scope message in Agent Builder's general settings. Optionally, configure an escalation action within the out-of-scope path to route to a human agent or provide a support link.")
                    ]
                ),
                StudyObjective(
                    id: "agents-hybrid-reasoning",
                    title: "Explain the components and benefits of hybrid reasoning, including how Agent Script functions in Canvas and Script View",
                    topics: [
                        StudyTopic(id: "agents-hybrid-reasoning-1", number: 1, question: "What hybrid reasoning means in Agentforce: the combination of deterministic scripted paths with LLM-driven reasoning.", answer: "Hybrid reasoning means an agent can follow deterministic, authored paths (via Agent Script conditionals, sequenced actions, and `available when` guards) for predictable, compliance-critical scenarios while simultaneously using full LLM reasoning for open-ended, flexible conversations. The same agent handles both: scripted paths for 'collect account number → verify → process' and free-form LLM for 'explain my bill in detail.'"),
                        StudyTopic(id: "agents-hybrid-reasoning-2", number: 2, question: "Canvas View in Agent Builder: the visual node-based interface for authoring Agent Script flows.", answer: "Canvas View displays the agent's subagent structure, action nodes, decision branches, and routing logic as a visual flowchart. Nodes are connected by arrows showing conversation flow. Admins can drag-and-drop actions, add branches, and visualize the entire agent topology. Best for understanding overall architecture and presenting to non-technical stakeholders."),
                        StudyTopic(id: "agents-hybrid-reasoning-3", number: 3, question: "Script View in Agent Builder: the list-based / structured representation of an Agent Script.", answer: "Script View shows the Agent Script in its structured text/YAML format directly in the browser. It exposes all properties (conditionals, variable bindings, action parameters) not fully visible in Canvas. Preferred by developers who need precise control, want to copy/paste snippets, or are debugging syntax issues. Script View is the ground truth — Canvas View renders from it."),
                        StudyTopic(id: "agents-hybrid-reasoning-4", number: 4, question: "The key benefit of hybrid reasoning: enabling predictable compliance-critical conversation paths alongside flexible LLM responses.", answer: "In regulated industries (financial services, healthcare), certain steps MUST happen in a specific order with no LLM latitude — e.g., identity verification before account access. Hybrid reasoning lets admins script those critical paths deterministically (guaranteed execution order, no model improvisation) while preserving LLM flexibility for the surrounding conversation. One agent handles both structured and unstructured interactions."),
                        StudyTopic(id: "agents-hybrid-reasoning-5", number: 5, question: "How Agent Script nodes branch deterministically based on conversation variable values.", answer: "Agent Script supports conditional branching using `available when` guards and `instructions: ->` syntax that evaluates current variable state. For example: if @variables.identity_verified == true, the order action becomes available; otherwise, an identity verification action is the only available choice. The LLM cannot bypass these guards — they are evaluated before the LLM sees the available action set."),
                        StudyTopic(id: "agents-hybrid-reasoning-6", number: 6, question: "How Agent Script nodes branch based on detected user intent versus explicit variable conditions.", answer: "Intent-based branching: the LLM selects which subagent or action to invoke based on semantic matching of the user's message to action/topic descriptions — this is soft routing. Variable-based branching: `available when` conditions evaluate hard boolean logic against stored variable values — this is deterministic routing. Both can coexist: deterministic gates filter available options, then the LLM picks among the allowed options."),
                        StudyTopic(id: "agents-hybrid-reasoning-7", number: 7, question: "The node types available in Agent Script — action nodes, message nodes, and branch/condition nodes.", answer: "Action nodes: invoke a configured agent action (Flow, Apex, prompt template, external service) — the agent 'does something'. Message nodes: send a static or template-based response to the user without invoking an action — useful for greetings, confirmations, error messages. Branch/Condition nodes: evaluate variable state or output flags and route conversation flow to different paths. Transition nodes: move conversation to a different subagent.")
                    ]
                ),
                StudyObjective(
                    id: "agents-security",
                    title: "Explain the security context in which the agent is actually running, and how it impacts agent action execution",
                    topics: [
                        StudyTopic(id: "agents-security-1", number: 1, question: "The Agent User model: how Agentforce creates and uses a dedicated integration user (the agent's run-as user) to execute actions.", answer: "Each Agentforce agent is associated with a dedicated Einstein Agent User — a specially licensed Salesforce user account. All action executions (Flow invocations, Apex calls, record reads/writes) run in the context of this agent user's identity. This ensures consistent, auditable data access regardless of which end-user is conversing with the agent."),
                        StudyTopic(id: "agents-security-2", number: 2, question: "How the agent's run-as user profile and permission sets determine which records and fields the agent can read or write.", answer: "The Einstein Agent User's profile, permission sets, and sharing rules define the agent's data access exactly as they would for any Salesforce user. If the agent user lacks read access to Account records, the agent cannot query Accounts. Admins must explicitly assign the correct object permissions, FLS, and sharing access to the agent user — 'Insufficient Privileges' errors during action execution typically trace back to this."),
                        StudyTopic(id: "agents-security-3", number: 3, question: "The difference between the end-user's session permissions and the agent's run-as user permissions, and which context applies when an action updates a record.", answer: "Action execution uses the AGENT'S run-as user permissions — NOT the end-user's session. Even if the conversing end-user cannot view a record, the agent (running as its own user) may be able to — and vice versa. This is an important security consideration: the agent user should be granted only the minimum permissions needed for its configured actions (principle of least privilege)."),
                        StudyTopic(id: "agents-security-4", number: 4, question: "Named credentials in agent actions: when a Named Credential is required versus when the run-as user's session is used.", answer: "Named Credentials: required when an agent action calls an EXTERNAL system (REST API, SOAP endpoint) that requires authentication. The Named Credential stores the endpoint URL and auth credentials securely. Run-as user session: used for internal Salesforce data operations (record CRUD, SOQL via Flow/Apex). External callouts always need Named Credentials — internal operations use the agent user's Salesforce session."),
                        StudyTopic(id: "agents-security-5", number: 5, question: "Whether Flows invoked by an agent action run in system mode or user mode by default, and how this impacts record access.", answer: "Flows invoked by agent actions run in USER MODE by default (with sharing) — they respect the agent user's sharing rules and FLS. This means Flows are NOT system-level bypasses. If a Flow needs system-level access (e.g., to query records outside the agent user's sharing), it must be explicitly configured to 'Run in System Context Without Sharing' — a deliberate, privileged choice that should be audited carefully.")
                    ]
                ),
                StudyObjective(
                    id: "agents-api",
                    title: "Given a scenario, identify when it's appropriate to use Agent API",
                    topics: [
                        StudyTopic(id: "agents-api-1", number: 1, question: "What is Agent API: the REST API surface that allows external applications to programmatically start sessions and exchange messages with an Agentforce agent.", answer: "Agent API is a Salesforce REST API that enables external applications (mobile apps, third-party portals, custom web experiences) to programmatically interact with an Agentforce agent. Callers can start sessions, send conversational messages turn-by-turn, and receive agent responses — all via standard HTTP REST calls, authenticated via OAuth 2.0."),
                        StudyTopic(id: "agents-api-2", number: 2, question: "Business scenarios where Agent API is the correct integration choice.", answer: "Use Agent API when: embedding an Agentforce agent into a custom mobile app not built on Salesforce Experience Cloud; integrating the agent into a third-party customer portal (e.g., a custom React or Angular app); powering a chatbot on a non-Salesforce website; or building programmatic agent interactions in backend services or automated testing frameworks."),
                        StudyTopic(id: "agents-api-3", number: 3, question: "The distinction between using Agent API (external invocation) versus deploying a channel (native Salesforce-managed channel).", answer: "Native channels (Messaging for In-App and Web, Slack, email): Salesforce manages the channel infrastructure, conversation routing, and UI — admin configures in Setup, no code needed for channel layer. Agent API: the external application owns the channel (UI, routing, session management) — Salesforce provides agent intelligence only. Use native channels for speed/simplicity; use Agent API for custom channel ownership and full UI control."),
                        StudyTopic(id: "agents-api-4", number: 4, question: "Required Agent API parameters for session creation and turn-by-turn message exchange.", answer: "Session creation (POST /einstein/ai-agent/v1/sessions): required params — agentId (the agent's unique identifier). Message exchange (POST /einstein/ai-agent/v1/sessions/{sessionId}/messages): required params — sessionId, message text, sequence ID. Each call returns the agent's response text and any action outputs. Headers require: Authorization: Bearer [OAuth token], Content-Type: application/json."),
                        StudyTopic(id: "agents-api-5", number: 5, question: "The Agent API session lifecycle: creating, sending messages, and terminating sessions.", answer: "1. POST /sessions → returns sessionId. 2. POST /sessions/{sessionId}/messages → send user message, receive agent response. Repeat for each turn. 3. DELETE /sessions/{sessionId} → explicitly terminate the session when conversation ends. Orphaned sessions (not deleted) consume agent capacity and accrue credits. Always implement session cleanup in your calling application, especially on user logout or timeout."),
                        StudyTopic(id: "agents-api-6", number: 6, question: "OAuth authentication requirements for calling the Agentforce Agent API.", answer: "The calling application must obtain an OAuth 2.0 access token from Salesforce using a Connected App. Recommended flow for server-to-server: OAuth 2.0 JWT Bearer Token flow (no user interaction required). For user-initiated contexts: OAuth 2.0 Authorization Code flow. The access token is passed in the Authorization header of every Agent API request. The Connected App must have the appropriate OAuth scopes for Agentforce.")
                    ]
                ),
                StudyObjective(
                    id: "agents-deterministic",
                    title: "Given a use case, manage deterministic behavior for the agent using mechanisms like filters, variables, and template expressions",
                    topics: [
                        StudyTopic(id: "agents-deterministic-1", number: 1, question: "What is the purpose of topic filters in an Agentforce custom topic?", answer: "Topic filters are conditions that restrict WHEN a topic is eligible for the agent to use. They act as pre-routing gates: if the filter condition is not met, the topic is hidden from the LLM's consideration entirely, even if the user's utterance would otherwise match. They enforce hard constraints on topic availability based on conversation context, user attributes, or variable state."),
                        StudyTopic(id: "agents-deterministic-2", number: 2, question: "How do topic filters constrain which user inputs the agent responds to?", answer: "Topic filters evaluate against conversation variables or system context BEFORE the LLM performs topic matching. Only topics whose filters evaluate to TRUE are presented to the LLM as candidates. Example: a 'Premium Account' topic only becomes available when @variables.account_tier == 'Premium'. Standard users never see this topic's behavior, regardless of what they say."),
                        StudyTopic(id: "agents-deterministic-3", number: 3, question: "A company wants its Service Agent to respond only to inquiries about a specific product line and ignore all other topics. Which Agent Builder configuration achieves this?", answer: "Configure the relevant topics to include only that product line's subject matter in their descriptions and instructions. For all other topics: either do not create them (they simply don't exist), or use topic filters/instructions that explicitly out-of-scope non-product inquiries. Additionally, configure the agent's global instructions with: 'This agent only assists with [Product Line] inquiries. Politely decline all other requests.'"),
                        StudyTopic(id: "agents-deterministic-4", number: 4, question: "When should an administrator use an input variable rather than hardcoding a value inside an agent action's instructions?", answer: "Use input variables when: the value changes per conversation or user (e.g., account number, product selection); the value is captured from user input during the conversation; the value is passed between actions (output of action A feeds input of action B); or when the same action is reused in multiple contexts requiring different parameter values. Hardcode only truly static values that never change."),
                        StudyTopic(id: "agents-deterministic-5", number: 5, question: "How do output variables enable data to be passed from one action to a subsequent action within the same agent topic?", answer: "When an action executes, it can store its output in a named conversation variable (e.g., @variables.case_number = action output). A subsequent action in the same topic can then reference @variables.case_number as an input parameter. This enables chained workflows: lookup action returns customer ID → update action uses that customer ID as input — all within a single conversation turn or across turns."),
                        StudyTopic(id: "agents-deterministic-6", number: 6, question: "How do topic-level instructions differ from action-level instructions in controlling agent behavior?", answer: "Topic-level instructions: apply throughout the entire topic, shaping the LLM's overall behavior, tone, and decision-making within that topic (e.g., 'Always confirm the customer's email before proceeding.'). Action-level instructions: apply only when that specific action is being invoked, providing precise guidance on HOW to call the action and handle its output (e.g., 'If the lookup returns no results, inform the user and offer to escalate.')."),
                        StudyTopic(id: "agents-deterministic-7", number: 7, question: "An administrator needs the agent to always confirm a customer's account number before processing a request. Which configuration enforces this deterministic step?", answer: "1. Create a conversation variable: @variables.account_number. 2. Create an 'Account Verification' action that captures and validates the account number, storing it in @variables.account_number. 3. Configure all processing actions with an `available when: @variables.account_number != null` guard. 4. Add topic instructions: 'Always collect and verify the customer account number before taking any action.' This combination of variable gate + `available when` + instructions enforces the order deterministically."),
                        StudyTopic(id: "agents-deterministic-8", number: 8, question: "How can an administrator utilize the Agent Builder preview to debug variable state and topic routing during an interaction?", answer: "In Agent Builder's Preview pane: conduct a test conversation, then examine the conversation trace panel (visible in the right-side debug view). The trace shows: which topic was selected for each turn, which action was invoked, the input/output values of each action call, and the current state of all conversation variables. If routing is incorrect, compare the user utterance against topic descriptions and refine description specificity.")
                    ]
                ),
                StudyObjective(
                    id: "agents-channels",
                    title: "Explain the process for connecting agents to various channels such as digital experience, email, voice, and Slack",
                    topics: [
                        StudyTopic(id: "agents-channels-1", number: 1, question: "What steps are required to connect an Agentforce Service Agent deployment to an Experience Cloud digital site?", answer: "1. Create/activate the Agentforce Service Agent. 2. In Agent Builder, create a Deployment for 'Messaging for In-App and Web'. 3. Copy the generated embedded service code snippet. 4. In Experience Builder, add the Embedded Messaging component to the desired pages and paste the snippet. 5. Configure branding, pre-chat fields, and offline settings. 6. Publish the Experience Cloud site. The agent appears as a chat widget on the site."),
                        StudyTopic(id: "agents-channels-2", number: 2, question: "How does an administrator configure an Agentforce agent to receive and respond to inbound email inquiries as a channel?", answer: "Email channel for Agentforce requires Salesforce's Email-to-Case or Einstein Email Bots configuration: 1. Set up Email-to-Case routing addresses. 2. In Agentforce, configure an Email channel deployment linked to that routing address. 3. The agent reads inbound emails, generates responses using configured topics/actions, and either auto-replies or queues the response for human review. Requires Messaging or Service Cloud licenses."),
                        StudyTopic(id: "agents-channels-3", number: 3, question: "What configuration is required to enable an Agentforce agent in Slack?", answer: "1. In Agent Builder, create a Deployment of type 'Slack'. 2. Connect your Salesforce org to the Slack workspace via Setup > Slack. 3. Authorize the Salesforce app in Slack. 4. The agent appears as a Slack App/bot that employees can message directly or mention in channels. Requires Slack Integration license and the agent to be an Employee Agent type. Service Agents cannot be deployed to Slack."),
                        StudyTopic(id: "agents-channels-4", number: 4, question: "What are the configuration requirements and limitations for deploying a Service Agent to SMS or WhatsApp?", answer: "Requirements: Salesforce Messaging for In-App and Web, with a configured Messaging Channel for SMS (via Salesforce-managed SMS number) or WhatsApp (via WhatsApp Business API partner). Setup: Setup > Messaging Settings > New Channel. Limitations: voice/audio not supported; rich media support varies; WhatsApp requires pre-approved message templates for outbound initiation; compliance requirements (TCPA for SMS) must be managed separately."),
                        StudyTopic(id: "agents-channels-5", number: 5, question: "What channel-specific deployment settings must be configured independently when the same agent is deployed to both web chat and email channels?", answer: "Each channel requires its own Deployment record with channel-specific settings: web chat needs the embedded service code snippet, branding, offline behavior, and pre-chat form; email needs routing address mapping, reply format, and subject line handling. Topic availability, escalation queues, and response tone instructions may also need to differ per channel. The same underlying agent logic powers both, but deployment configs are independent."),
                        StudyTopic(id: "agents-channels-6", number: 6, question: "How is an Agentforce Service Agent configured to seamlessly hand off or escalate a conversation to an Omni-Channel queue for human assistance?", answer: "1. In Agent Builder, add the @utils.escalate utility action to the relevant topic. 2. Configure the escalation target: an Omni-Channel queue or skill group. 3. Set escalation conditions in topic instructions (e.g., 'If the customer expresses frustration or the issue cannot be resolved in 2 attempts, escalate'). 4. The conversation transcript is transferred to the human agent with full history preserved. Requires Omni-Channel and Service Cloud.")
                    ]
                ),
                StudyObjective(
                    id: "agents-employee-vs-service",
                    title: "Given a scenario, identify when to use an Employee or Service agent",
                    topics: [
                        StudyTopic(id: "agents-employee-vs-service-1", number: 1, question: "What is the primary distinction between an Employee Agent and a Service Agent in terms of intended audience and channel?", answer: "Service Agent: designed for CUSTOMER-facing interactions — deployed to web chat, messaging, email, voice. Customers (unauthenticated or externally authenticated) interact with it. Employee Agent: designed for INTERNAL employee interactions — deployed to Salesforce CRM, Slack, or internal portals. Authenticated Salesforce users (employees) interact with it using their own CRM session."),
                        StudyTopic(id: "agents-employee-vs-service-2", number: 2, question: "Which agent type is designed specifically for customer-facing interactions through digital experience sites and messaging channels?", answer: "Service Agent. It supports deployment to Experience Cloud sites, messaging channels (SMS, WhatsApp, in-app web chat), email, and voice. It includes built-in capabilities for pre-chat forms, Omni-Channel escalation, conversation transcripts, and customer identity handling. Employee Agents cannot be deployed to these external-facing channels."),
                        StudyTopic(id: "agents-employee-vs-service-3", number: 3, question: "What capabilities and built-in topics differentiate a Sales Agent from an Employee Agent?", answer: "The Agentforce Sales Agent is a specialized pre-built agent with standard topics for: qualifying prospects, drafting outreach emails (via Einstein Sales Emails), summarizing opportunities, and generating call prep. It integrates with CRM Opportunity and Lead data. An Employee Agent is a more general-purpose internal assistant — it does not have these sales-workflow-specific built-in topics by default."),
                        StudyTopic(id: "agents-employee-vs-service-4", number: 4, question: "What are the licensing prerequisites for Employee Agent versus Service Agent?", answer: "Service Agent: requires Agentforce Service Agent license (per conversation credit model). The agent user needs a specific Einstein Agent User license. Employee Agent: requires Agentforce Employee Agent license (per user seat model, not per conversation). Admins need to assign the correct permission set licenses in Setup. Both require Einstein Generative AI to be enabled at the org level."),
                        StudyTopic(id: "agents-employee-vs-service-5", number: 5, question: "A company wants to automate customer support deflection across a web chat channel before routing to a human. Which agent type?", answer: "Service Agent. It is the only type deployable to external web chat channels and supports Omni-Channel escalation for the human handoff. Configure topics for common deflection scenarios (FAQ, order status, returns) and set escalation conditions for complex or unresolvable issues."),
                        StudyTopic(id: "agents-employee-vs-service-6", number: 6, question: "A sales team wants an AI assistant in Salesforce CRM to help reps draft outreach emails, summarize opportunities, and generate call prep notes. Which agent type?", answer: "Employee Agent (specifically, an Agentforce Sales Agent or a custom Employee Agent built for sales). It runs within the Salesforce CRM UI in the context of the logged-in rep's session, can access the rep's Opportunity/Lead records, and can invoke actions like Einstein Sales Emails and record summarization. The rep interacts with it directly in the CRM sidebar or command bar.")
                    ]
                ),
                StudyObjective(
                    id: "agents-topics-actions",
                    title: "Given a scenario, select and configure standard topics, custom topics, standard agent actions, and custom agent actions",
                    topics: [
                        StudyTopic(id: "agents-topics-actions-1", number: 1, question: "What is the difference between a standard topic and a custom topic in Agent Builder?", answer: "Standard topics: pre-built by Salesforce for common use cases (e.g., 'Answer Questions with Knowledge', 'Transfer to Agent', 'End Chat'). They come with pre-configured descriptions, instructions, and actions — ready to use out-of-the-box with minimal setup. Custom topics: created by the admin for org-specific business processes. The admin defines the topic description, instructions, and associated actions from scratch."),
                        StudyTopic(id: "agents-topics-actions-2", number: 2, question: "When should an administrator use a standard topic versus a custom topic?", answer: "Use standard topics when: the business need maps directly to a pre-built capability (knowledge Q&A, escalation, conversation close), and the default behavior requires minimal customization. Use custom topics when: the business process is org-specific (e.g., 'Process Product Return Request'), requires custom data lookups, involves proprietary workflows, or needs instructions tailored to your business context and terminology."),
                        StudyTopic(id: "agents-topics-actions-3", number: 3, question: "Which standard topics are available out-of-the-box for a Service Agent?", answer: "Standard Service Agent topics include: 'Answer Questions with Knowledge' (retrieves answers from ADL/Knowledge), 'Transfer to Agent' (Omni-Channel escalation), 'End Chat' (closes the conversation gracefully), 'Send Follow-up Message' (post-conversation outreach), and 'Fallback' (out-of-scope handling). Exact availability depends on org licenses and enabled features."),
                        StudyTopic(id: "agents-topics-actions-4", number: 4, question: "What capability does each standard topic provide for a Service Agent?", answer: "'Answer Questions with Knowledge': uses the Agentforce Data Library to retrieve and present knowledge article content. 'Transfer to Agent': invokes @utils.escalate to route to an Omni-Channel queue. 'End Chat': sends a farewell message and closes the session. 'Fallback/Out of Scope': handles unmatched utterances with a configurable message. These topics are production-ready with sensible defaults."),
                        StudyTopic(id: "agents-topics-actions-5", number: 5, question: "Which action types can be created as custom agent actions in Agentforce?", answer: "Custom agent actions can be backed by: Autolaunched Flows (most common for declarative logic), Apex @InvocableMethod classes (for complex logic, callouts, or performance-sensitive operations), Prompt Templates (Flex type, for AI-generated content), External Services (for OpenAPI-spec-defined REST APIs), and MCP server tools (developer preview). Each type has different implementation requirements."),
                        StudyTopic(id: "agents-topics-actions-6", number: 6, question: "When should an administrator use a standard agent action versus building a custom Flow-based agent action?", answer: "Use standard agent actions when: Salesforce provides an out-of-the-box action that meets the requirement (e.g., 'Send Email', 'Create Record', 'Query Records'). Use custom Flow-based actions when: the logic requires multiple steps, conditional branching, transformations, custom error handling, or data from multiple objects not available in standard actions. Flows offer the most flexibility without requiring code."),
                        StudyTopic(id: "agents-topics-actions-7", number: 7, question: "When is an Apex-based agent action preferred over a Flow-based agent action?", answer: "Prefer Apex when: performance is critical (complex SOQL, bulk processing), the logic requires advanced error handling, you need to make external callouts with custom auth logic, the logic cannot be expressed in Flow (complex string manipulation, external library calls), or governor limit optimization is required. Apex actions execute faster than equivalent Flows for computationally intensive tasks."),
                        StudyTopic(id: "agents-topics-actions-8", number: 8, question: "What are the prerequisites for exposing an Apex method or a Flow as a custom agent action?", answer: "Flow: must be an Autolaunched Flow (not screen flows). Input variables must have 'Available for Input' checked. Output variables must have 'Available for Output' checked. Apex: the method must have @InvocableMethod annotation. Must use wrapper input/output classes (not primitive-only). Method must be public/global. The Apex class must be deployed to the org. Both must be activated/deployed before appearing in Agent Builder."),
                        StudyTopic(id: "agents-topics-actions-9", number: 9, question: "How does the action description field affect the reasoning engine's ability to correctly invoke the right action?", answer: "The action description is the PRIMARY signal the LLM uses to decide whether to invoke that action for a given user request. A vague description ('Handles requests') leads to random or missed invocations. A precise description ('Retrieves the status of a customer's order when the customer asks about their order, shipment, or delivery') dramatically improves correct action selection. The description should include trigger phrases and the action's specific purpose."),
                        StudyTopic(id: "agents-topics-actions-10", number: 10, question: "Best practices for naming and describing custom agent actions to ensure the reasoning engine invokes them correctly.", answer: "Name: use verb-noun format ('Get Order Status', 'Create Support Case', 'Send Confirmation Email'). Description: 1. State WHEN to invoke (trigger conditions). 2. State WHAT it does (specific outcome). 3. Include representative user phrases (synonyms the user might say). 4. State any prerequisites ('Use this action only after customer identity has been verified'). 5. Keep it under 1,000 characters — concise and specific beats verbose and vague."),
                        StudyTopic(id: "agents-topics-actions-11", number: 11, question: "How are inputs from a user's utterance mapped to the specific parameters of a custom agent action?", answer: "The LLM extracts parameter values from the conversation context (current utterance + conversation history + variables) and maps them to the action's defined input parameters. Input parameter descriptions are critical — they tell the LLM what value to extract ('The customer's 10-digit account number mentioned in the conversation'). For required inputs the LLM cannot find, the agent asks the user a clarifying question before invoking the action."),
                        StudyTopic(id: "agents-topics-actions-12", number: 12, question: "A business requires an agent to call an external REST API that uses a custom OAuth scheme not supported by a standard action. Which action type?", answer: "Apex-based agent action. Implement the external REST callout in an Apex @InvocableMethod using Salesforce Named Credentials for the endpoint authentication. Apex gives full control over HTTP headers, auth flows, request/response parsing, and error handling — capabilities not available in declarative Flow HTTP calls or External Services when using non-standard OAuth schemes."),
                        StudyTopic(id: "agents-topics-actions-13", number: 13, question: "A company wants the agent to summarize case records and send an email confirmation to the customer in a single interaction. Which combination of topics and action types?", answer: "Create a custom topic (e.g., 'Case Resolution'). Within it, configure two actions: 1. A Flex Prompt Template action to generate the case summary (grounded with case record data). 2. A Flow action or standard 'Send Email' action to send the confirmation email, using the summary output from action 1 as the email body. Chain the actions by storing the summary in a conversation variable and passing it to the email action.")
                    ]
                )
            ]
        ),
        // Section 4: Testing, Deployment, & Maintenance (34 topics)
        StudySection(
            id: "testing-deployment",
            title: "Testing, Deployment, & Maintenance",
            color: Color(red: 0.80, green: 0.52, blue: 0.10),
            lightColor: Color(red: 1.0, green: 0.96, blue: 0.88),
            icon: "wrench.and.screwdriver",
            objectives: [
                StudyObjective(
                    id: "testing-center",
                    title: "Given a scenario, test an agent using Testing Center",
                    topics: [
                        StudyTopic(id: "testing-center-1", number: 1, question: "What is the Agentforce Testing Center?", answer: "The Agentforce Testing Center is a built-in Salesforce tool (accessible via Setup > Agents > [Agent] > Testing Center) that enables admins and developers to create automated test suites validating agent behavior. It supports rule-based assertions (exact action/topic match) and AI-graded assertions (semantic response quality evaluation) across repeatable test cases without needing a live user conversation."),
                        StudyTopic(id: "testing-center-2", number: 2, question: "What types of agent behaviors does the Agentforce Testing Center allow an administrator to validate?", answer: "Testing Center validates: topic routing accuracy (did the agent route to the correct topic?), action invocation (did the agent call the expected action?), action input accuracy (were the correct parameters passed?), response quality (did the agent's response meet the expected quality?), conversation flow (did the agent follow the expected multi-turn path?), and out-of-scope handling (did the agent correctly decline off-topic requests?)."),
                        StudyTopic(id: "testing-center-3", number: 3, question: "What inputs are required to define a test case in Agentforce Testing Center?", answer: "A test case requires: (1) The user utterance(s) — the simulated conversation input. (2) Expected topic — the topic the agent should route to. (3) Expected action — the action(s) the agent should invoke. (4) Expected response — the expected output text (for AI-graded assertions) or exact match text (for rule-based assertions). (5) Test data context (optional) — a specific record ID to ground the conversation."),
                        StudyTopic(id: "testing-center-4", number: 4, question: "How does an administrator create a test case in Agentforce Testing Center?", answer: "1. Navigate to Setup > Agents > [Agent] > Testing Center. 2. Click New Test Case. 3. Enter the user utterance and expected conversation path. 4. Define assertions: select assertion type (Topic Routing, Action Invocation, or Response Quality), specify expected value. 5. Optionally link a test record for grounding. 6. Save and add to a test suite. Run the suite to see pass/fail results."),
                        StudyTopic(id: "testing-center-5", number: 5, question: "How is test data managed and utilized within Testing Center to simulate real-world CRM scenarios?", answer: "Test cases can reference specific Salesforce record IDs (e.g., a specific Case or Account record) to ground the agent's actions in realistic data. The agent executes actions against the referenced record during the test run. Best practice: maintain dedicated test records in sandbox with known, stable data — avoid using production records or records that may be modified between test runs."),
                        StudyTopic(id: "testing-center-6", number: 6, question: "How are test suites organized and run in Agentforce Testing Center?", answer: "Test suites are named collections of test cases. Run suites manually on-demand or schedule them. When run: each test case executes in sequence, the agent processes the utterance(s) in a simulated session, assertions are evaluated against the actual output, and results are stored with pass/fail/warning status. Suites can be organized by topic, feature, or deployment phase (regression, smoke tests)."),
                        StudyTopic(id: "testing-center-7", number: 7, question: "What categories of assertions are available in Agentforce Testing Center?", answer: "Three assertion categories: 1. Topic Assertion — validates that the correct topic was selected. 2. Action Assertion — validates that the expected action was invoked (and optionally that specific inputs were passed). 3. Response Quality Assertion — uses an LLM judge to evaluate whether the agent's free-text response meets specified quality criteria."),
                        StudyTopic(id: "testing-center-8", number: 8, question: "What does each assertion type in Agentforce Testing Center validate?", answer: "Topic Assertion: did the agent route to topic X? Pass = correct topic selected. Action Assertion: did the agent call action Y? Pass = action invoked (with optional input parameter matching). Response Quality: does the response satisfy a specified criterion (e.g., 'Is the response professional and mentions the order number')? Evaluated by a judge LLM on a semantic scoring scale — pass = score above defined threshold."),
                        StudyTopic(id: "testing-center-9", number: 9, question: "How does Agentforce Testing Center use an LLM judge to evaluate open-ended conversational agent outputs?", answer: "For Response Quality assertions, a separate LLM (the 'judge') is given: the agent's actual response, the expected output criteria specified by the test author, and optionally the conversation context. The judge scores the response on a semantic scale (typically 1–5 or pass/fail) based on whether the response meets the criteria. This enables evaluation of subjective qualities (tone, completeness, accuracy) that exact-match rules cannot assess."),
                        StudyTopic(id: "testing-center-10", number: 10, question: "Which types of agent failures can be reliably detected by automated Agentforce Testing Center test suites?", answer: "Reliably detected: incorrect topic routing (wrong topic selected), missing action invocations (action not called when it should be), incorrect action input mapping (wrong parameter values), broken actions (action returns error), out-of-scope mishandling (agent responds to a request it should decline), and regression failures after configuration changes."),
                        StudyTopic(id: "testing-center-11", number: 11, question: "Which types of agent failures require manual conversation testing to uncover?", answer: "Manual testing needed for: edge cases with highly varied natural language phrasing; multi-turn conversation coherence (does the agent maintain context correctly across many turns?); emotional/tone nuances in responses; real-time action latency and timeout behavior; UI/channel-specific rendering issues; and failure modes that only emerge under specific sequential conversation paths not anticipated in test case design."),
                        StudyTopic(id: "testing-center-12", number: 12, question: "How should an administrator interpret pass, fail, and warning results in Testing Center?", answer: "Pass: the assertion condition was fully met — no action needed. Fail: the assertion condition was not met — investigate the conversation trace to determine if the issue is in topic description, action description, action configuration, or instruction quality. Warning (for AI-graded assertions): the response scored below the threshold but above a minimum — review carefully; may indicate borderline quality. Treat warnings as issues requiring investigation."),
                        StudyTopic(id: "testing-center-13", number: 13, question: "A development team wants to verify that a newly configured custom topic routes user intents correctly before deploying to production. Which Testing Center feature should they use?", answer: "Create a test suite with Topic Routing assertions. Write test cases covering: (1) utterances that SHOULD route to the new topic, (2) utterances that should route to OTHER topics (negative testing), and (3) utterances that are ambiguous between the new topic and similar topics. Run the suite and review routing accuracy. Refine topic descriptions and instructions based on failures before deploying.")
                    ]
                ),
                StudyObjective(
                    id: "testing-evaluations",
                    title: "Explain how Testing Center evaluations work",
                    topics: [
                        StudyTopic(id: "testing-evaluations-1", number: 1, question: "The difference between a rule-based assertion (exact action match) and an AI-graded assertion (semantic similarity).", answer: "Rule-based assertion: deterministic — the test passes ONLY if the specified exact condition is met (e.g., action 'Get_Order_Status' was invoked, topic 'Order Management' was selected). Binary: pass or fail — no interpretation. AI-graded assertion: uses an LLM judge that semantically evaluates whether the response meets a described quality criterion. Non-binary — scored on a scale. Can assess meaning, completeness, and tone."),
                        StudyTopic(id: "testing-evaluations-2", number: 2, question: "How does Testing Center use a judge LLM to score free-text agent responses against expected output, and the scoring scale it uses.", answer: "The judge LLM receives: (1) the agent's actual response text, (2) the expected output description authored by the test creator, (3) conversation context. It evaluates the response against the criteria using natural language reasoning and returns a score. Salesforce uses a 1–5 scale where 5 is fully meets criteria and 1 is fails to meet criteria. The test author sets a minimum passing score threshold (e.g., 4 or higher = pass)."),
                        StudyTopic(id: "testing-evaluations-3", number: 3, question: "What metadata is captured for each test run in Testing Center — inputs, actual outputs, scores, and execution trace.", answer: "Each test run captures: input utterance(s), resolved conversation context, actual topic selected, actual actions invoked with inputs/outputs, actual agent response text, assertion results (pass/fail/score for each assertion), execution timestamp, and any errors. The execution trace (LLMStep, FunctionStep, ReasoningStep) shows the exact reasoning path. All run history is retained for comparison across runs."),
                        StudyTopic(id: "testing-evaluations-4", number: 4, question: "How does Testing Center evaluate whether an agent response meets expected output quality criteria?", answer: "The test author writes a natural-language quality criterion (e.g., 'The response confirms the order number and provides an estimated delivery date without making promises about specific dates.'). At test execution, the judge LLM reads the actual response and the criterion, then reasons about whether the criterion is satisfied. This mirrors how a human QA reviewer would evaluate response quality — but at scale and repeatably."),
                        StudyTopic(id: "testing-evaluations-5", number: 5, question: "How does Testing Center evaluate whether an agent routed to the correct topic and executed the expected action?", answer: "Testing Center has access to the full agent execution trace. After the test conversation runs, it reads the trace to find: which topic the reasoning engine selected (compared against the Topic assertion's expected topic), which actions were invoked (compared against Action assertions' expected action names). These are deterministic checks — no LLM judgment needed. Pass/fail is binary based on exact match."),
                        StudyTopic(id: "testing-evaluations-6", number: 6, question: "How judge LLM Einstein AI credits are consumed during Testing Center output-quality evaluations.", answer: "Each Response Quality assertion consumes Einstein AI credits for the judge LLM inference call. The cost is separate from the agent conversation credits. Factor this into test budget planning — large test suites with many Response Quality assertions can consume significant credits, especially if run frequently (e.g., on every deployment). Rule-based assertions (Topic/Action) do NOT consume AI credits."),
                        StudyTopic(id: "testing-evaluations-7", number: 7, question: "How agent conversation credits are consumed when running test cases in Testing Center.", answer: "Each test case run simulates a real agent conversation — conversation credits ARE consumed per turn (20 credits per agent action execution). Multiple-turn test cases consume credits for each turn. Plan test suite runs accordingly, especially in environments where credits are limited. Consider running full regression suites only at key deployment checkpoints, with lighter smoke-test suites for routine changes.")
                    ]
                ),
                StudyObjective(
                    id: "deploy-template",
                    title: "Identify the considerations for deploying a template from sandbox to production",
                    topics: [
                        StudyTopic(id: "deploy-template-1", number: 1, question: "The requirement to reactivate a prompt template in production after deployment.", answer: "Prompt templates deploy in DRAFT state, regardless of their state in sandbox. They must be manually reactivated in production after deployment. This is a common gotcha — leaving templates in Draft means no automations, agent actions, or user triggers can invoke them. Build 'activate all deployed templates' into your post-deployment runbook."),
                        StudyTopic(id: "deploy-template-2", number: 2, question: "How LLM model availability in production versus sandbox can affect prompt template behavior after deployment.", answer: "Sandbox and production orgs may have different models configured or available. If a template explicitly references a model that exists in sandbox but is not provisioned in production (or is blocked), the template will fail on invocation. Always verify that the assigned model is available and active in the target production org BEFORE deploying — and test the template's output, since even the same model can behave slightly differently across environments."),
                        StudyTopic(id: "deploy-template-3", number: 3, question: "Post-deployment verification of a prompt template in production: recommended practice.", answer: "After deploying and activating a template in production: open Prompt Builder (production), navigate to the template, use the Preview pane against a real production record (not a test record), review the resolved prompt and LLM response for correctness and quality. Only THEN enable any automations or agent actions that invoke the template. Never enable production automations until the template output is verified in context."),
                        StudyTopic(id: "deploy-template-4", number: 4, question: "Which grounding resources (Flows, Apex) must be deployed alongside a prompt template.", answer: "All dependent components must be deployed BEFORE the prompt template: Autolaunched Flows used as grounding sources, Apex classes used as grounding invocable methods, any referenced custom objects or fields that the merge fields resolve against, and Named Credentials if any grounding source makes external callouts. Deploy order: dependent metadata first, prompt template last."),
                        StudyTopic(id: "deploy-template-5", number: 5, question: "Which prompt template definition metadata must be included when deploying from sandbox to production.", answer: "The PromptTemplate metadata type encapsulates: template body text (with merge fields), grounding configuration (grounding source references), model assignment, template type (Field Generation, Flex, etc.), and target object/field configuration. Include the entire PromptTemplate metadata type in your deployment package — partial deployments of sub-components are not supported."),
                        StudyTopic(id: "deploy-template-6", number: 6, question: "Which dependent object or field metadata must be present in production for a prompt template to execute successfully.", answer: "All custom objects, custom fields, and related objects referenced by merge fields in the template must exist in production with matching API names. If a merge field references MyObject__c.Custom_Field__c and that field doesn't exist in production, the template will fail on activation or invocation. Run a pre-deployment metadata audit comparing sandbox and production object/field presence."),
                        StudyTopic(id: "deploy-template-7", number: 7, question: "The PromptTemplate metadata API type: what it encompasses and how to retrieve and deploy it using SFDX or change sets.", answer: "PromptTemplate metadata type encompasses: template definition, body, type, object/field targets, grounding source references, model assignment. Retrieve via SFDX: `sf project retrieve start -m PromptTemplate:MyTemplateName`. Deploy via SFDX: `sf project deploy start -m PromptTemplate:MyTemplateName`. Change sets: add PromptTemplate components in the change set manifest in Setup > Outbound Change Sets. Include all dependent components in the same package.")
                    ]
                ),
                StudyObjective(
                    id: "deploy-agent",
                    title: "Identify the considerations for deploying an agent from sandbox to production",
                    topics: [
                        StudyTopic(id: "deploy-agent-1", number: 1, question: "Which metadata components are included in an Agentforce agent deployment package?", answer: "An agent deployment package includes: Bot/BotVersion metadata (the agent definition), GenAiPlannerBundle (Agent Script topics, actions, instructions), AiAuthoringBundle (.agent file and sub-components), referenced Flows (Autolaunched), Apex classes (InvocableMethod actions), PromptTemplates (if used as actions), Permission Sets (agent user access), Connected App settings (if channel-specific), and any custom objects/fields referenced by actions."),
                        StudyTopic(id: "deploy-agent-2", number: 2, question: "How can Salesforce DX (sf CLI) and change sets each be used to deploy Agentforce agent metadata?", answer: "SFDX: retrieve the AiAuthoringBundle + Bot + GenAiPlannerBundle + all dependencies using sf project retrieve, version them in Git, then deploy using sf project deploy start. Supports CI/CD pipelines. Change Sets: add Bot, GenAiPlannerBundle, and dependency components to an Outbound Change Set in sandbox, upload, then deploy in production via Inbound Change Sets. SFDX recommended for repeatability and automation; Change Sets for simpler org-to-org migrations."),
                        StudyTopic(id: "deploy-agent-3", number: 3, question: "What Agent User permission set and profile considerations must an administrator address when promoting an agent from sandbox to production?", answer: "The Einstein Agent User must exist in production with the correct: profile (Agent User profile), permission sets (Agentforce PSLs, object/field access PSs), and role/sharing settings. Permission set XML with <agentAccesses> elements must reference the agent's developer_name exactly. Create and assign the agent user in production BEFORE deploying the agent metadata, or activation will fail with 'Agent User not found' errors."),
                        StudyTopic(id: "deploy-agent-4", number: 4, question: "How should an administrator manage prompt template versions and activation states when deploying across sandbox and production environments?", answer: "Deploy process: 1. Deploy PromptTemplate metadata (arrives as Draft in production). 2. Activate the correct template version in production manually. 3. Verify previous versions are deactivated. 4. Test the active template in Preview against a production record. Key risk: if multiple versions exist in production from prior deployments, ensure the correct version is activated. Document which version is current in your change management records."),
                        StudyTopic(id: "deploy-agent-5", number: 5, question: "How do connected app settings and channel deployment configurations affect the sandbox-to-production migration?", answer: "Channel deployments (Messaging for In-App and Web, Slack) have their own metadata components and Connected App references that are environment-specific. The endpoint URLs, connected app consumer keys/secrets, and embedded code snippets are different between sandbox and production. These must be reconfigured in production — they cannot simply be copied from sandbox. Plan for manual post-deployment channel configuration steps."),
                        StudyTopic(id: "deploy-agent-6", number: 6, question: "What agent configuration elements cannot be migrated via metadata deployment and must be manually reconfigured in production?", answer: "Cannot be migrated via metadata: channel deployment activation (must re-enable in production), agent activation state (must activate in production), conversation transcript retention settings (org-level settings), Omni-Channel routing configuration details (queue assignments), and real-time monitoring tool setup. These require manual post-deployment admin steps in production Setup."),
                        StudyTopic(id: "deploy-agent-7", number: 7, question: "Are Agentforce Data Library configurations, indexes, and unstructured data files migratable via standard metadata deployments?", answer: "NO. ADL configurations (source definitions, indexing settings) and the actual indexed content (file contents, crawled web pages, Knowledge index) are NOT part of standard Salesforce metadata and cannot be migrated via SFDX or change sets. ADL must be set up independently in production: create source definitions, upload/connect content sources, trigger indexing, and verify 'Ready' status before enabling knowledge-grounded agent capabilities in production.")
                    ]
                )
            ]
        ),
        // Section 5: Governance & Observability (40 topics)
        StudySection(
            id: "governance",
            title: "Governance & Observability",
            color: Color(red: 0.13, green: 0.59, blue: 0.33),
            lightColor: Color(red: 0.88, green: 0.98, blue: 0.92),
            icon: "shield.checkered",
            objectives: [
                StudyObjective(
                    id: "gov-monitoring",
                    title: "Explain the process for managing and monitoring agents",
                    topics: [
                        StudyTopic(id: "gov-monitoring-1", number: 1, question: "What happens to in-flight conversations when an Agentforce agent is deactivated mid-session?", answer: "In-flight (active) conversations are NOT immediately terminated when an agent is deactivated. Active sessions continue to their natural end or timeout. New conversation sessions CANNOT be started with a deactivated agent — users attempting to start new chats will receive an 'unavailable' response. Plan deactivations during low-traffic windows to minimize impact on ongoing conversations."),
                        StudyTopic(id: "gov-monitoring-2", number: 2, question: "What are the Draft, Active, and Inactive agent states in Agentforce?", answer: "Draft: agent is being configured — cannot accept new conversations. Cannot be deployed to channels. Active: agent is live and accepting conversations from configured channels. Configuration changes require creating a new version. Inactive: agent was previously active, now suspended — no new conversations. Prior conversations are preserved. Use Inactive for temporary takedowns; Delete (if supported) for permanent removal."),
                        StudyTopic(id: "gov-monitoring-3", number: 3, question: "How does agent versioning work in Agentforce?", answer: "Agentforce maintains a versioned history of agent configurations. Each time configuration changes are published, a new version is created. Previous versions are preserved as read-only snapshots (version-suffixed bundles). Only one version can be Active at a time. Admins can review prior versions for audit purposes. Rolling back to a prior version requires redeploying and activating the previous version's metadata."),
                        StudyTopic(id: "gov-monitoring-4", number: 4, question: "Which Salesforce tool allows an administrator to view live and historical Agentforce conversation transcripts?", answer: "Agentforce Conversation Transcripts — accessible via: Setup > Agents > Conversation Transcripts, OR the Messaging Sessions object in Salesforce (for Service Cloud channels), OR via SOQL on the MessagingSession and ConversationEntry objects. The Agentforce Analytics dashboard also surfaces conversation-level data. Requires the 'View Agentforce Conversations' permission."),
                        StudyTopic(id: "gov-monitoring-5", number: 5, question: "What conversational content is captured in an Agentforce conversation transcript?", answer: "Transcripts capture: all user utterances (verbatim), all agent responses (verbatim), timestamps per message, topic routing decisions, action invocations (action name, inputs, outputs), conversation session metadata (start/end time, channel, session ID), escalation events (if/when transferred to human), and any error events. Variable state is not captured in the transcript — use the debugging trace for that."),
                        StudyTopic(id: "gov-monitoring-6", number: 6, question: "A support lead reports that the agent gave a customer incorrect information. How does an administrator access the specific conversation transcript to investigate?", answer: "1. Get the approximate time/date and channel from the support lead. 2. Navigate to Setup > Agents > Conversation Transcripts, or query MessagingSession WHERE CreatedDate = [date range] AND Channel = [channel]. 3. Locate the specific session (search by customer identifier, channel, or timestamp). 4. Open the transcript to review the exact utterances, topic routing, and action outputs that led to the incorrect response. 5. Use the Conversation Debugger in Agent Builder to replay and trace the reasoning."),
                        StudyTopic(id: "gov-monitoring-7", number: 7, question: "How does the Conversation Debugger in Agent Builder help administrators trace unexpected topic or action selection?", answer: "The Conversation Debugger allows admins to replay a specific conversation session step by step within Agent Builder. For each turn, it shows: the full assembled system prompt (what the LLM saw), the LLM's reasoning output (which topic/action it selected and why), action inputs/outputs, and variable state at each step. This makes it possible to pinpoint exactly why the agent made an unexpected decision — whether the cause is topic description, action description, instruction conflict, or variable state."),
                        StudyTopic(id: "gov-monitoring-8", number: 8, question: "A company needs to audit all configuration changes made to an Agentforce agent over the past 30 days. Which Salesforce feature provides this audit trail?", answer: "Salesforce Setup Audit Trail (Setup > Security > View Setup Audit Trail). It captures all Setup-level configuration changes with: the user who made the change, the type of change, timestamp, and old/new values. For Agentforce specifically: topic additions/edits, action changes, instruction edits, and activation/deactivation events are logged. Export the audit trail CSV and filter for Agentforce-related event types."),
                        StudyTopic(id: "gov-monitoring-9", number: 9, question: "What is the role of the Agent User account in Agentforce?", answer: "The Agent User is a dedicated Salesforce integration user that serves as the identity under which all agent actions execute. It provides: data security isolation (actions only access data the agent user can access), auditable data access (all DML operations are attributed to the agent user, not the end-user), and license management (the Einstein Agent User license is assigned to this account, not to individual conversation users)."),
                        StudyTopic(id: "gov-monitoring-10", number: 10, question: "What is the process for transferring an Agentforce conversation to a human agent?", answer: "1. The agent invokes the @utils.escalate utility action (configured in the topic). 2. Salesforce Omni-Channel receives the escalation request and routes it to the appropriate queue or skill group. 3. The full conversation transcript (all prior turns) is transferred to the human agent's console. 4. The human agent sees the context immediately and can continue the conversation. 5. The Agentforce session closes; the human agent's Messaging session opens."),
                        StudyTopic(id: "gov-monitoring-11", number: 11, question: "How can a supervisor monitor an escalation from an Agentforce agent to a human agent in real time using Omni-Channel Supervisor?", answer: "In Omni-Channel Supervisor (Service Console > Omni-Channel Supervisor tab): supervisors see real-time work item routing, including conversations transferred from Agentforce. They can view: which agent received the escalated conversation, the customer's wait time, the conversation status, and CSAT flags. Supervisors can also monitor the conversation (with appropriate permissions) to coach or assist the human agent in real time."),
                        StudyTopic(id: "gov-monitoring-12", number: 12, question: "A support manager wants to review all conversations where the agent escalated to a human without resolving the issue. Which feature surfaces this most efficiently?", answer: "Agentforce Analytics dashboard (Setup > Agents > Analytics) — filter by 'Escalation Rate' and 'Resolution: Not Resolved'. This surfaces conversations where escalation occurred AND the issue was marked as unresolved. For deeper analysis: create a report on the MessagingSession object with filters for EscalationFlag = true AND ResolutionStatus = 'Not Resolved'. Export and review escalation transcripts for pattern analysis."),
                        StudyTopic(id: "gov-monitoring-13", number: 13, question: "What is Utterance Analysis in Agentforce?", answer: "Utterance Analysis is an Agentforce Analytics feature that aggregates and clusters actual user utterances from production conversations — especially those that resulted in out-of-scope responses, misrouting, or low CSAT. It uses ML clustering to group similar utterances together, revealing patterns in what users are asking that the agent is not handling well. This surfaces 'blind spots' in the agent's topic coverage."),
                        StudyTopic(id: "gov-monitoring-14", number: 14, question: "How does Utterance Analysis aggregate unclassified or misrouted customer utterances to surface patterns?", answer: "Utterance Analysis collects utterances from conversations flagged as: out-of-scope, escalated to human, or low-rated. It applies NLP clustering algorithms to group semantically similar utterances. The resulting clusters are ranked by frequency — showing which unhandled intents appear most often. Admins see a clustered view like: '47 utterances about password reset issues → mapped to no existing topic.'"),
                        StudyTopic(id: "gov-monitoring-15", number: 15, question: "After Utterance Analysis reveals that a cluster of user messages is consistently misrouted to the wrong topic, what administrative actions should be taken?", answer: "1. Review the cluster — understand what users are actually asking (the underlying intent). 2. Determine if a new topic is needed or if an existing topic's description needs refinement. 3. If creating a new topic: write a precise description capturing the intent, add appropriate actions, test with representative utterances from the cluster. 4. If refining: update the misrouted topic's description to be more specific and add boundary conditions. 5. Re-run Testing Center suites to validate the fix before deploying."),
                        StudyTopic(id: "gov-monitoring-16", number: 16, question: "What setup steps are required before an administrator can access Agentforce conversation transcripts in production?", answer: "1. Einstein Generative AI must be enabled. 2. The agent must be activated and have handled real conversations. 3. The admin must have the 'View Agentforce Conversations' permission (or System Administrator profile). 4. For channel-specific transcripts (Messaging): Messaging must be enabled and configured. 5. Data retention settings must not have purged transcripts before the admin tries to access them."),
                        StudyTopic(id: "gov-monitoring-17", number: 17, question: "How does the Agentforce Testing Center function as a pre-activation monitoring tool?", answer: "Testing Center validates agent behavior BEFORE the agent is activated in production. Running the full test suite pre-activation catches: topic routing regressions, broken actions (post-code deployment), response quality degradation after configuration changes, and permission/access issues with the agent user. Treating Testing Center runs as a deployment gate — require all tests to pass before activation — effectively makes it a monitoring/quality gate."),
                        StudyTopic(id: "gov-monitoring-18", number: 18, question: "How do Agentforce conversation transcript data retention policies work?", answer: "Transcript retention is governed by the org's standard data retention settings and any GDPR/compliance-driven data deletion policies. By default, MessagingSession and ConversationEntry records are retained indefinitely unless explicitly purged. Orgs with compliance requirements should configure scheduled data deletion jobs or use Salesforce Data Mask and Data Retention policies to automatically purge old transcripts per policy timelines."),
                        StudyTopic(id: "gov-monitoring-19", number: 19, question: "What determines which Agentforce agent is invoked when a Messaging for In-App and Web channel is configured in an org with multiple active agents?", answer: "The specific Messaging Channel deployment configuration determines which agent is invoked. Each Messaging Channel (Setup > Messaging Settings > Channels) is linked to one specific Agentforce Deployment. When a user initiates a chat on that channel's embedded code snippet, the agent linked to that deployment handles the conversation. Different channels (e.g., website chat vs. product support portal) can link to different agents.")
                    ]
                ),
                StudyObjective(
                    id: "gov-analytics",
                    title: "Explain agent analytics and agent optimization",
                    topics: [
                        StudyTopic(id: "gov-analytics-1", number: 1, question: "What key performance metrics does the Agentforce Analytics dashboard expose out of the box?", answer: "Out-of-the-box metrics include: Deflection Rate (conversations resolved without human intervention), Escalation Rate (conversations transferred to human agent), Resolution Rate (percentage of conversations where the user's issue was resolved), CSAT (customer satisfaction score collected post-conversation), Topic Classification Accuracy (% of intents correctly routed), Action Error Rate (% of action invocations that failed), and Conversation Volume (total sessions by channel and time period)."),
                        StudyTopic(id: "gov-analytics-2", number: 2, question: "How is deflection rate defined and calculated in Agentforce Analytics?", answer: "Deflection Rate = (Conversations resolved by the agent without human escalation / Total conversations) × 100. 'Resolved by agent' means: the user's issue was addressed, no escalation occurred, and the conversation ended (either user-closed or agent-closed with confirmation). High deflection = agent effectively handling requests. Low deflection = agent failing to resolve or escalating excessively — investigate topic coverage and action effectiveness."),
                        StudyTopic(id: "gov-analytics-3", number: 3, question: "How does Agentforce use conversation-level feedback (thumbs up/down or CSAT scores) to surface optimization opportunities?", answer: "Negative feedback signals (thumbs down, low CSAT) are linked to the specific conversation transcripts and actions that preceded them. Agentforce Analytics clusters negative feedback by topic and action to identify which parts of the agent experience are underperforming. This directs admins to review specific topic instructions, action descriptions, or response quality for the topics/actions associated with poor feedback."),
                        StudyTopic(id: "gov-analytics-4", number: 4, question: "Which metric specifically measures how often the reasoning engine correctly classified a user's intent to the intended topic?", answer: "Topic Classification Accuracy (also called Intent Recognition Rate in some contexts). It measures the percentage of user utterances that were routed to the topic that the admin intended (as defined in Testing Center test cases, or as validated by human review of transcripts). A score below ~85% typically indicates topic descriptions need refinement to better discriminate between topics."),
                        StudyTopic(id: "gov-analytics-5", number: 5, question: "How should an administrator interpret a consistently low topic classification accuracy score in Agentforce Analytics?", answer: "Low classification accuracy indicates the reasoning engine is confusing topics — utterances meant for topic A are being routed to topic B. Root causes: overlapping topic descriptions that use similar language, topics that are too broadly defined, insufficient distinction between closely related topics, or ambiguous user utterances that legitimately fit multiple topics. Fix: sharpen topic descriptions, add exclusion language ('Do NOT use this topic for X'), and add more specific routing examples."),
                        StudyTopic(id: "gov-analytics-6", number: 6, question: "How can Einstein Conversation Mining or its Agentforce Analytics equivalent identify recurring unhandled user intents?", answer: "Utterance Analysis (Agentforce's conversation mining feature) clusters out-of-scope and unresolved utterances, ranking clusters by frequency. Review the top clusters — high-frequency clusters represent unmet demand that should become new agent topics. For each cluster: assess business value of handling it, estimate implementation effort, then prioritize topic creation accordingly."),
                        StudyTopic(id: "gov-analytics-7", number: 7, question: "What is the recommended iterative workflow for optimizing agent topic descriptions and action instructions based on analytics findings?", answer: "Iterative optimization cycle: 1. Review Analytics dashboard — identify metrics below threshold (e.g., topic accuracy < 85%, CSAT < 4.0). 2. Drill into underperforming topics/actions using conversation transcripts. 3. Identify root cause (description clarity, action logic, instruction conflict). 4. Draft and test changes in sandbox using Testing Center. 5. Deploy changes. 6. Monitor metrics for improvement (allow 1–2 weeks for data to accumulate). Repeat."),
                        StudyTopic(id: "gov-analytics-8", number: 8, question: "How do action-level metrics (action invocation count, action error rate) help determine whether a problem originates in topic routing or action execution?", answer: "If Topic Classification Accuracy is HIGH but CSAT is LOW: the routing is correct but action execution is failing — investigate action error rates and action output quality. If Topic Classification Accuracy is LOW: the problem is in routing, not execution. If a specific action has a high error rate: investigate the action's Flow/Apex, the agent user's permissions for that action, or the data quality of action inputs. Isolating the metric layer narrows the root cause efficiently."),
                        StudyTopic(id: "gov-analytics-9", number: 9, question: "An agent is correctly identifying topics but users are ending conversations without resolution. Which Analytics view best isolates this problem?", answer: "Filter by: Topic = [correct topic], Resolution Status = 'Unresolved', Escalation = False (user left without escalating). This surfaces conversations where routing was correct but the agent failed to resolve the issue within the topic. Review these transcripts to determine: did the action fail? Did the response not address the user's actual need? Was the action invoked but with wrong parameters? Was the topic instruction too restrictive?"),
                        StudyTopic(id: "gov-analytics-10", number: 10, question: "How does Agentforce Analytics segment performance data by channel to enable channel-specific optimization?", answer: "The Agentforce Analytics dashboard includes a channel dimension filter (web chat, email, SMS, Slack, voice). All key metrics (deflection, CSAT, escalation, classification accuracy) are segmented by channel. This reveals channel-specific patterns — e.g., voice channel has higher escalation rate than web chat. Different channels may need different topic instructions, response length guidelines, or action configurations optimized for channel context."),
                        StudyTopic(id: "gov-analytics-11", number: 11, question: "What is the relationship between Testing Center evaluation scores and production Agentforce analytics metrics?", answer: "Testing Center scores are leading indicators — they predict production performance. If Testing Center Response Quality scores drop after a configuration change, expect production CSAT to drop. If Testing Center topic routing tests fail, expect production Topic Classification Accuracy to drop. Treat Testing Center scores as proxy metrics for production performance — use them to catch regressions BEFORE they impact real customers."),
                        StudyTopic(id: "gov-analytics-12", number: 12, question: "How can an administrator use the topic confusion or misrouting analytics report to rewrite topic descriptions?", answer: "The misrouting report shows confusion pairs: 'When users said X, the agent routed to Topic A but should have routed to Topic B.' For each confusion pair: (1) Read the actual user utterances. (2) Compare Topic A and Topic B descriptions — identify where they overlap. (3) Rewrite Topic B's description to explicitly exclude the utterance types that should stay in Topic A. (4) Add a boundary clause to Topic A: 'This topic does NOT handle [Topic B scenarios].' Test with the exact utterances from the report."),
                        StudyTopic(id: "gov-analytics-13", number: 13, question: "What is the Agent Optimization feature in Agentforce?", answer: "Agent Optimization is an AI-assisted feature that analyzes agent performance data (transcripts, CSAT, misrouting events) and automatically generates specific recommendations for improving topic descriptions, action instructions, or agent instructions. It surfaces these recommendations in the Agent Builder UI, allowing admins to review and selectively apply them rather than manually diagnosing configuration issues."),
                        StudyTopic(id: "gov-analytics-14", number: 14, question: "What is the end-to-end process for an administrator to review, accept, and validate an Agent Optimization recommendation?", answer: "1. Navigate to Agent Builder > Optimization tab. 2. Review the recommendation (e.g., 'Rewrite Topic X description to include keyword Y'). 3. Review the supporting evidence (sample misrouted transcripts that motivated the recommendation). 4. Apply the recommendation to a sandbox agent copy (not directly to production). 5. Run Testing Center suites to validate the recommendation improves metrics without causing regressions. 6. Deploy the change to production. 7. Monitor analytics for improvement."),
                        StudyTopic(id: "gov-analytics-15", number: 15, question: "How does Utterance Analysis differ from aggregate Agentforce Analytics dashboards?", answer: "Analytics dashboards: show aggregated NUMERIC metrics (deflection %, CSAT scores, volume trends) over time — the 'what' of performance. Utterance Analysis: shows actual USER LANGUAGE from conversations — the 'why'. Analytics tells you 'CSAT dropped 10%.' Utterance Analysis tells you 'Users are asking about account merges, which no topic handles.' One is quantitative measurement; the other is qualitative diagnostic — both are needed together."),
                        StudyTopic(id: "gov-analytics-16", number: 16, question: "What permissions, feature licenses, or administrator setup steps are required before Agentforce Analytics dashboards become available?", answer: "Requirements: (1) Einstein Generative AI enabled. (2) Agentforce agent must be activated and have processed real conversations. (3) Admin must have 'View Agentforce Analytics' permission (or Sys Admin). (4) Einstein Analytics/CRM Analytics license may be required for advanced analytics features. (5) Conversation data retention settings must allow data to accumulate (dashboards show no data if transcripts are purged immediately)."),
                        StudyTopic(id: "gov-analytics-17", number: 17, question: "A business stakeholder asks for a weekly report on Agentforce deflection rate trends broken down by product line. Which Salesforce tooling combination best satisfies this requirement?", answer: "Agentforce Analytics for raw deflection data export + CRM Analytics (Tableau CRM) or standard Salesforce Reports for custom report creation and scheduling. Process: 1. Export Agentforce Analytics data to MessagingSession objects tagged with product line (via conversation variables stored to records). 2. Create a Salesforce Report on MessagingSession with product line grouping and deflection rate calculation. 3. Schedule the report to email the stakeholder weekly."),
                        StudyTopic(id: "gov-analytics-18", number: 18, question: "How does Agentforce Analytics track and surface the performance impact of topic or action instruction changes made after an optimization cycle?", answer: "Agentforce Analytics includes time-series views that plot metrics over time. After deploying optimization changes, mark the change date (deployment timestamp) and compare the metric trend BEFORE vs. AFTER the change date. Most dashboards allow date range filtering — compare the prior 7 days to the post-change 7 days. Meaningful sample sizes require adequate conversation volume; low-traffic agents may need 2–4 weeks of post-change data."),
                        StudyTopic(id: "gov-analytics-19", number: 19, question: "Which two actions should an administrator take first when Agentforce Analytics shows a sudden spike in escalation rate following a recent deployment?", answer: "1. Review the Setup Audit Trail for configuration changes in the deployment (what changed in topic descriptions, action configurations, or instructions). 2. Filter conversation transcripts to the spike period and sample 5–10 escalated conversations to identify the common failure pattern. These two actions quickly isolate whether the spike is caused by a specific configuration change (rollback candidate) or a new type of user request the agent wasn't prepared for (topic gap)."),
                        StudyTopic(id: "gov-analytics-20", number: 20, question: "What does a high no-match or out-of-scope rate in Agentforce Analytics indicate about agent topic coverage?", answer: "A high out-of-scope rate indicates the agent's configured topics do not cover a significant portion of what users are asking. Users are arriving with real, legitimate needs that the agent simply has no topic to handle. Run Utterance Analysis on the out-of-scope utterances to discover which intents are unhandled, then prioritize new topic creation. A high out-of-scope rate in a mature agent also indicates customer expectations have shifted beyond the agent's original scope."),
                        StudyTopic(id: "gov-analytics-21", number: 21, question: "Does Agentforce Analytics support automated alerts when key metrics such as escalation rate or CSAT cross defined thresholds?", answer: "Out of the box, Agentforce Analytics does not natively support threshold-based alerts as a built-in feature. Workaround options: (1) CRM Analytics with Einstein Discovery and scheduled alert reports. (2) Build a Salesforce Flow that queries MessagingSession aggregate data on a schedule and sends notifications when thresholds are crossed. (3) Use third-party BI tools (Tableau, Power BI) connected to Salesforce data for alert functionality.")
                    ]
                )
            ]
        ),
        // Section 6: Multi-Agent Orchestration (9 topics)
        StudySection(
            id: "multi-agent",
            title: "Multi-Agent Orchestration",
            color: Color(red: 0.86, green: 0.21, blue: 0.27),
            lightColor: Color(red: 1.0, green: 0.91, blue: 0.92),
            icon: "point.3.connected.trianglepath.dotted",
            objectives: [
                StudyObjective(
                    id: "multi-soma",
                    title: "Given a scenario, determine whether a Single-Agent (SOMA) architecture is appropriate for scalability and control",
                    topics: [
                        StudyTopic(id: "multi-soma-1", number: 1, question: "What SOMA (Single-Agent Orchestration and Multi-Action) architecture is and the core principle of keeping all logic within one agent.", answer: "SOMA is an architectural pattern where a single Agentforce agent handles the full range of user intents through multiple topics and actions — without delegating to separate specialized sub-agents. The core principle: maximize what one agent can do before introducing the complexity of multi-agent orchestration. One agent, many capabilities, simpler governance and debugging."),
                        StudyTopic(id: "multi-soma-2", number: 2, question: "The scalability limitations of a single-agent approach as topics and actions grow.", answer: "Practical limits: Agent Builder becomes unwieldy with 20+ topics and 50+ actions. Topic description collisions increase — the LLM struggles to accurately route when too many similar-seeming topics exist. System prompt length grows with each topic/action description, consuming context window. Testing complexity multiplies. Debugging becomes harder when a single agent handles many domains. These tipping points motivate splitting to multi-agent."),
                        StudyTopic(id: "multi-soma-3", number: 3, question: "Scenarios where SOMA is sufficient versus where multi-agent architecture is required.", answer: "SOMA is sufficient: the agent handles 1–3 clearly distinct domains with <15 topics total, routing is accurate in testing, team can maintain a single agent configuration. Multi-agent required: genuinely different domains need different system-level behaviors (e.g., one domain requires strict identity verification, another is open-access); parallel task execution is needed (two domains processing simultaneously); topics exceed ~20 with significant routing confusion; or different teams own different agent domains and need independent configuration control."),
                        StudyTopic(id: "multi-soma-4", number: 4, question: "How agents call sub-agents in Agentforce multi-agent architecture: the orchestrating (parent) agent invokes a sub-agent as an agent action.", answer: "In multi-agent architecture, the orchestrating (parent) agent has an action configured that invokes a sub-agent by its ID. The parent passes context (conversation history, variables) to the sub-agent. The sub-agent processes the request using its own topics and actions, then returns its output (a response or structured data) to the parent agent. The parent continues its own reasoning loop using the sub-agent's output. Sub-agents are specialized; the parent orchestrates.")
                    ]
                ),
                StudyObjective(
                    id: "multi-protocols",
                    title: "Explain the purpose of existing open standard multi-agent protocols such as MCP and A2A",
                    topics: [
                        StudyTopic(id: "multi-protocols-1", number: 1, question: "Model Context Protocol (MCP): what it is, which organization defined it, and how it standardizes tool/context exposure from servers to LLM agents.", answer: "MCP (Model Context Protocol) was defined by Anthropic and published as an open standard. It standardizes how LLM agents discover and use external tools, data sources, and context. MCP servers advertise their capabilities (tools, prompts, resources) in a standard format. MCP clients (LLM agents) connect to MCP servers and dynamically use the advertised tools. This eliminates the need for custom per-tool integration code for each agent-tool combination."),
                        StudyTopic(id: "multi-protocols-2", number: 2, question: "Agent-to-Agent (A2A) protocol: its purpose in enabling interoperable communication between independently built AI agents across platforms.", answer: "A2A (Agent-to-Agent) is an open protocol (supported by Google, Salesforce, and others) that defines how AI agents built on different platforms can discover, communicate with, and delegate tasks to each other. An A2A-compatible agent publishes an 'Agent Card' (a JSON descriptor of its capabilities, input/output schemas, and endpoints). Other A2A-compatible agents can discover this card and invoke the agent as if it were a service — enabling cross-platform agent collaboration."),
                        StudyTopic(id: "multi-protocols-3", number: 3, question: "The difference between MCP and A2A: MCP standardizes how agents access tools and context, while A2A standardizes how agents communicate tasks to one another.", answer: "MCP is about the AGENT-TO-TOOL relationship: how an agent discovers and calls external tools, APIs, or data sources exposed by an MCP server. Think of MCP as 'how the agent gets its hands on external capabilities.' A2A is about the AGENT-TO-AGENT relationship: how one AI agent sends a task to another AI agent (possibly on a different platform) and receives results. Think of A2A as 'how agents collaborate with each other as peers.'"),
                        StudyTopic(id: "multi-protocols-4", number: 4, question: "How Agentforce supports MCP: using MCP server connections to expose external tools to an Agentforce agent without custom code per tool.", answer: "Agentforce can connect to MCP servers via Setup > MCP Server Management (developer preview as of 2025). Admin registers an MCP server (URL, auth), fetches its advertised assets (tools, prompts, resources), and whitelists selected tools. Once whitelisted, the MCP server's tools appear as available agent actions in Agent Builder — no custom code needed per tool. The agent's reasoning engine can invoke these tools just like native Flow/Apex actions."),
                        StudyTopic(id: "multi-protocols-5", number: 5, question: "How Agentforce supports A2A: publishing an Agentforce agent as an A2A-discoverable endpoint using an Agent Card.", answer: "Agentforce agents can be published as A2A endpoints — Salesforce generates an Agent Card (JSON descriptor) for the agent that A2A-compatible systems can discover via a standard discovery URL. External A2A-compatible agents (from Google, Microsoft, or other platforms) can then invoke the Agentforce agent as a participant in cross-platform multi-agent workflows. This enables enterprise scenarios where Agentforce handles Salesforce-specific tasks within a broader multi-vendor AI orchestration.")
                    ]
                )
            ]
        )
    ]
}
